insert into ccmas_eng values
  ('Agricultural and Bioresources Engineering', 'GET 101', 'Engineer in Society', '100 Level', 'first', 1, false, 'History, evolution and philosophy of science. engineering and technology. The engineering profession - engineering family (engineers, technologists, technicians and craftsmen), professional bodies and societies. Engineers'' code of conduct and ethics, and engineering literacy. Sustainable development goals (SDGs), innovation, infrastructures and nation building - economy, politics, business. Safety and risk analysis in engineering practice. Engineering competency skills - curriculum overview, technical, soft and digital skills. Guest seminars and invited lectures from different engineering professional associations.', '["History, evolution and philosophy of science","engineering and technology","The engineering profession - engineering family (engineers, technologists, technicians and craftsmen),...","Engineers'' code of conduct and ethics, and engineering literacy","Sustainable development goals (SDGs), innovation, infrastructures and nation building - economy, politics,...","Safety and risk analysis in engineering practice","Engineering competency skills - curriculum overview, technical, soft and digital skills","Guest seminars and invited lectures from different engineering professional associations"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'GET 102', 'Engineering Graphics and Solid Modelling I', '100 Level', 'second', 2, false, 'Introduction to design thinking and engineering graphics. First and third angle orthogonal projections. Isometric projections; sectioning, conventional practices, conic sections and development. Freehand and guided sketching - pictorial and orthographic. Visualisation and solid modelling in design, prototyping and product-making. User interfaces in concrete terms. Design, drawing, animation, rendering and simulation workspaces. Sketching of 3D objects. Viewports and sectioning to shop drawings in orthographic projections and perspectives. Automated viewports. Sheet metal and surface modelling. Material selection and rendering. This course will use latest professional design tools such as fusion 360, solid works, solid edge or equivalent.', '["Introduction to design thinking and engineering graphics","First and third angle orthogonal projections","Isometric projections","sectioning, conventional practices, conic sections and development","Freehand and guided sketching - pictorial and orthographic","Visualisation and solid modelling in design, prototyping and product-making","User interfaces in concrete terms","Design, drawing, animation, rendering and simulation workspaces"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ABE 102', 'Introduction to Agricultural and Biosystem Engineering', '100 Level', 'second', 2, false, '', '[]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ENT 211', 'Entrepreneurship and Innovation', '200 Level', 'first', 2, false, '', '[]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'GET 201', 'Applied Electricity I', '200 Level', 'first', 3, false, 'Fundamental concepts: Electric fields, charges, magnetic fields. current, B-H curves Kirchhoff''s laws, superposition. Thevenin, Norton theorems, Reciprocity, RL, RC, RLC circuits. DC, AC bridges, Resistance, Capacitance, Inductance measurement, Transducers, Single phase circuits, Complex j - notation, AC circuits, impedance, admittance, susceptance.', '["Fundamental concepts: Electric fields, charges, magnetic fields","current, B-H curves Kirchhoff''s laws, superposition","Thevenin, Norton theorems, Reciprocity, RL, RC, RLC circuits","DC, AC bridges, Resistance, Capacitance, Inductance measurement, Transducers, Single phase circuits,..."]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'GET 202', 'Engineering Materials', '200 Level', 'second', 3, false, 'Basic material science; atomic structure, atomic bonding and crystal structures. Engineering materials situating metals and alloys; metals and alloys, classifications of metals, metal extraction processes using iron and steel (ferrous) and aluminium (nonferrous) as examples, phase diagrams/iron carbon diagrams, and mechanical workings of metals. Selection and applications of metals and alloys for specific applications in oil, aerospace, construction, manufacturing and transportation industries, among others. Ceramics (including glass); definition, properties, structure and classifications of ceramics. Bioactive and glass - ceramics. Toughing mechanism for ceramics. Polymers; definition of polymers as engineering materials, chemistry of polymeric materials, polymer crystallisation, polymer degradation and aging. Thermoplastic and thermosetting polymers and concepts of copolymers and homopolymers. Composites; definition, classification, characterisation, properties and composite. Applications of composites. Nanomaterials; definition, classification and applications of nanomaterials as emerging technology. Processing of nanomaterials including mechanical grinding, wet chemical synthesis, gas phase synthesis, sputtered plasma processing, microwave plasma processing and laser ablation. Integrity assessment of engineering materials; effect of engineering design, engineering materials processing, selection, manufacturing and assembling on the performance and service life of engineering materials. Metallography and fractography of materials. Mechanical testing (destructive testing) of materials such as compressive test, tensile test, hardness test, impact test, endurance limit and fatigue test. Non-destructive test (NDT) such as dye penetrant, x-ray and eddy current.', '["Basic material science","atomic structure, atomic bonding and crystal structures","Engineering materials situating metals and alloys","metals and alloys, classifications of metals, metal extraction processes using iron and steel (ferrous)...","Selection and applications of metals and alloys for specific applications in oil, aerospace, construction,...","Ceramics (including glass)","definition, properties, structure and classifications of ceramics","Bioactive and glass - ceramics"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'GET 204', 'Students Workshop Practice', '200 Level', 'second', 2, false, 'The course comprises general, mechanical and electrical components: supervised hands-on experience in safe usage of tools and machines for selected tasks; Use of measuring instruments (calipers, micrometers, gauges, sine bar, wood planners, saws, sanders, and', '["The course comprises general, mechanical and electrical components: supervised hands-on experience in safe...","Use of measuring instruments (calipers, micrometers, gauges, sine bar, wood planners, saws, sanders, and"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'GET 205', 'Fundamentals of Fluid Mechanics', '200 Level', 'first', 3, false, 'Fluid properties, hydrostatics, fluid dynamics using principles of mass, momentum and energy conservation from a control volume approach. Flow measurements in pipes, dimensional analysis, and similitude, 2-dimensional flows. Hydropower systems.', '["Fluid properties, hydrostatics, fluid dynamics using principles of mass, momentum and energy conservation...","Flow measurements in pipes, dimensional analysis, and similitude, 2-dimensional flows","Hydropower systems"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'GET 206', 'Fundamentals of Thermodynamics', '200 Level', 'second', 3, false, 'Basic concepts, definitions and laws (quantitative relations of Zeroth, first, second and third laws of thermodynamics). Properties of pure substances: the two-property rule (P-V-T behaviour of pure substances and perfect gases); state diagrams. The principle of corresponding state; compressibility relations; reduced pressure; reduced volume; temperature; pseudo-critical constants. The ideal gas: specific heat, polytropic processes. Ideal gas cycles; Carnot; thermodynamic cycles, turbines, steam and gas, refrigeration. The first law of thermodynamics - heat and work, applications to open and closed systems. The steady flow energy equation (Bernoulli''s equation) and application. Second law of thermodynamics, heat cycles and efficiencies.', '["Basic concepts, definitions and laws (quantitative relations of Zeroth, first, second and third laws of...","Properties of pure substances: the two-property rule (P-V-T behaviour of pure substances and perfect gases)","state diagrams","The principle of corresponding state","compressibility relations","reduced pressure","reduced volume","temperature"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'GET 209', 'Engineering Mathematics I', '200 Level', 'first', 3, false, 'Limits, continuity, differentiation, introduction to linear first order differential equations, partial and total derivatives, composite functions, matrices and determinants, vector algebra, vector calculus, directional derivatives.', '["Limits, continuity, differentiation, introduction to linear first order differential equations, partial..."]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'GET 210', 'Engineering Mathematics II', '200 Level', 'second', 3, false, 'Introduction to ordinary differential equations (ODEs); theory, applications, methods of solution; second order differential equations. Advanced topics in calculus (vectors and vector-valued function, line integral, multiple integral and their applications). Elementary complex analysis including functions of complex variables, limits and continuity. Derivatives, differentiation rules and differentiation of integrals. Cauchy-Riemann equation, harmonic functions, basic theory of conformal mapping, transformation and mapping and its applications to engineering problems. Special functions.', '["Introduction to ordinary differential equations (ODEs)","theory, applications, methods of solution","second order differential equations","Advanced topics in calculus (vectors and vector-valued function, line integral, multiple integral and...","Elementary complex analysis including functions of complex variables, limits and continuity","Derivatives, differentiation rules and differentiation of integrals","Cauchy-Riemann equation, harmonic functions, basic theory of conformal mapping, transformation and mapping...","Special functions"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'GET 211', 'Computing and Software Engineering', '200 Level', 'first', 3, false, 'Introduction to computers and computing; computer organisation - data processing, memory, registers and addressing schemes; Boolean algebra; floating-point arithmetic; representation of non-numeric information; problem-solving and algorithm development; coding (solution design using flowcharts and pseudo codes). Data models and data structures; computer software and operating system; computer operators and operators precedence; components of computer programs; introduction to object oriented, structured and visual programming; use of MATLAB in engineering applications. ICT fundamentals, Internet of Things (IoT). Elements of software engineering.', '["Introduction to computers and computing","computer organisation - data processing, memory, registers and addressing schemes","Boolean algebra","floating-point arithmetic","representation of non-numeric information","problem-solving and algorithm development","coding (solution design using flowcharts and pseudo codes)","Data models and data structures"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ENT 312', 'Venture Creation', '300 Level', 'second', 2, false, 'Opportunity identification (sources of business opportunities in Nigeria, environmental scanning, demand and supply gap/unmet needs/market gaps/market research, unutilised resources, social and climate conditions and technology adoption gap). business development (business planning, market research). Entrepreneurial finance (venture capital, equity finance, micro-finance, personal savings, small business investment organizations and business plan competition). Entrepreneurial marketing and e-commerce (principles of marketing, customer acquisition & retention, B2B, C2C and B2C models of e-commerce, First Mover Advantage, E-commerce business models and successful e-commerce companies). Small business management/family business: Leadership & Management, basic book keeping, nature of family business and family business growth model. Negotiation and business communication (strategy and tactics of negotiation/bargaining, traditional and modern business communication methods). Opportunity discovery demonstrations (business idea generation presentations, business idea contest, brainstorming sessions, idea pitching). Technological solutions (The concept of market/customer solution, customer solution and emerging technologies, business applications of new technologies - artificial intelligence (AI), virtual/mixed reality (VR), Internet of things (IoTs), blockchain, cloud computing, renewable energy, etc. Digital business and e-commerce strategies).', '["Opportunity identification (sources of business opportunities in Nigeria, environmental scanning, demand...","business development (business planning, market research)","Entrepreneurial finance (venture capital, equity finance, micro-finance, personal savings, small business...","Entrepreneurial marketing and e-commerce (principles of marketing, customer acquisition & retention, B2B,...","Small business management/family business: Leadership & Management, basic book keeping, nature of family...","Negotiation and business communication (strategy and tactics of negotiation/bargaining, traditional and...","Opportunity discovery demonstrations (business idea generation presentations, business idea contest,...","Technological solutions (The concept of market/customer solution, customer solution and emerging..."]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'GET 304', 'Technical Writing and Communication', '300 Level', 'second', 3, false, 'A brief review of common pitfalls in writing. Principles of clear writing (punctuations and capitalization). Figures of speech. Units of grammar. Tenses and verb agreement. Active and passive sentences Lexis and structure Fog Index concept. Skills for communication and communication algorithm. Types and goals of communication; Interpersonal communication; features and the Finger Model or A,B,C,D,E of good interpersonal communication (accuracy of technical terms, brevity of expression, clarity of purpose, directness of focus and effectiveness of the report). Language and organisation of reports. Technical report writing skills(steps, problems in writing, distinguishing technical and other reports, significance, format and styles of writing technical reports). Different formats for communication; styles of correspondences - business report and proposal, business letter, memorandum, e-mails, etc. Proposals for projects and research; format, major steps and tips of grant-oriented proposals. Research reports(competency, major steps, components and formats of research reports and publishable communication). Sources and handling of data, tables, figures, equations and references in a report. Presentation skills; overview, tips, organisation, use of visual aids and practising of presentation. Intellectual property rights in research reports. Case studies of major engineering designs, proposals and industrial failures with professional presentation of reports.', '["A brief review of common pitfalls in writing","Principles of clear writing (punctuations and capitalization)","Figures of speech","Units of grammar","Tenses and verb agreement","Active and passive sentences Lexis and structure Fog Index concept","Skills for communication and communication algorithm","Types and goals of communication"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'GET 305', 'Engineering Statistics and Data Analysis', '300 Level', 'first', 3, false, 'Descriptive statistics, frequency distribution, populations and sample, central tendency, variance data sampling, mean, median, mode, mean deviation, percentiles, etc. Probability. Binomial, Poisson hyper-geometric, normal distributions, etc. Statistical inference intervals,', '["Descriptive statistics, frequency distribution, populations and sample, central tendency, variance data...","Probability","Binomial, Poisson hyper-geometric, normal distributions, etc","Statistical inference intervals,"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'GET 306', 'Renewable Energy Systems and Technologies', '300 Level', 'second', 3, false, 'Current and potential future energy systems in Nigeria and globally - resources, extraction, concepts in energy conversion systems; parallels and differences in various conversion systems and end-use technologies, with emphasis on meeting 21st-century national, regional and global energy needs in a sustainable manner. Various energy technologies in each fuel cycle stage for fossil (oil, gas, synthetic), nuclear (fission and fusion) and renewable (solar, biomass, wind, hydro, and geothermal). Energy types, storage, transmission and conservation. Analysis of energy mixes within an engineering, economic and social context. Sustainable energy; emphasise sustainability in general and in the overall concept of sustainable development and the link this has with sustainable energy as the fundamental benefit of renewable energy. Practical Content: Simple measurement of solar radiation, bomb calorimeter determination of calorific value of fuels and biomass; measurement of the velocity of wind, waves and the energy that abound in them; laboratory production of biogas and determination of energy available in it; simple conversion of solar energy to electricity; transesterification of edible oil into biodiesel; simulation of geothermal energy; Geiger-Muller or Scintillation Counters'' determination of uranium or thorium energy; simple solid or salt storage of energy; hybrid application of renewable energy.', '["Current and potential future energy systems in Nigeria and globally - resources, extraction, concepts in...","parallels and differences in various conversion systems and end-use technologies, with emphasis on meeting...","Various energy technologies in each fuel cycle stage for fossil (oil, gas, synthetic), nuclear (fission...","Energy types, storage, transmission and conservation","Analysis of energy mixes within an engineering, economic and social context","Sustainable energy","emphasise sustainability in general and in the overall concept of sustainable development and the link...","Practical Content: Simple measurement of solar radiation, bomb calorimeter determination of calorific..."]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'GET 307', 'Introduction to Artificial Intelligence, Machine Learning and Convergent Technologies', '300 Level', 'first', 3, false, '', '[]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ABE 301', 'Design of Machine and Structural Elements', '300 Level', 'first', 2, false, 'Design of machine elements: Theories of failure. Design of shafts, belt and pulley drives, gears, sprockets, bolts and nuts, keys and keyways; selection of bearings. Practical session: Use of computer software in machine design. Design of structural elements: Definitions. Hooke''s law. Stress and strain due to loading. Torsion of circular members. Shear force. Bending moment and bending stresses in beams with symmetrical and combined loadings. Stress and strain transformation equations. Mohr cycle. Elastic buckling of columns. Design of beams using empirical methods and computer software. Design of columns using empirical methods and computer software. Group design assignment of machine or structural elements or complete system.', '["Design of machine elements: Theories of failure","Design of shafts, belt and pulley drives, gears, sprockets, bolts and nuts, keys and keyways","selection of bearings","Practical session: Use of computer software in machine design","Design of structural elements: Definitions","Hooke''s law","Stress and strain due to loading","Torsion of circular members"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ABE 302', 'Animal Production', '300 Level', 'second', 2, false, 'Course Contents Types of livestock (for eggs, milk, meat, wool, etc). distribution of livestock in Nigeria. Livestock housing. Livestock processing equipment.', '["Course Contents Types of livestock (for eggs, milk, meat, wool, etc)","distribution of livestock in Nigeria","Livestock housing","Livestock processing equipment"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ABE 303', 'Crop Production', '300 Level', 'first', 2, false, 'Classification and ecology of crops in Nigeria. Nutrient requirements and mineral nutrition of plants. Manures and fertilizers. Plant growth and development. Growth stages. Tillage and weed control. Other cultural practices. Cropping sequences and rotation. Farming systems. Production practices for specified crops. Conservation agriculture and sustainability in tropical agriculture.', '["Classification and ecology of crops in Nigeria","Nutrient requirements and mineral nutrition of plants","Manures and fertilizers","Plant growth and development","Growth stages","Tillage and weed control","Other cultural practices","Cropping sequences and rotation"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ABE 304', 'Farm Management, Rural Sociology and Agricultural Extension', '300 Level', 'second', 2, false, '', '[]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ABE 305', 'Soil Science', '300 Level', 'first', 2, false, '', '[]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ABE 306', 'Land Surveying and Geographic Information System', '300 Level', 'second', 2, false, '', '[]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ABE 307', 'Biosystems Engineering', '300 Level', 'first', 2, false, 'Course Contents Definitions. Modelling and design of fermentation systems. Microbial growth kinetics. Design of bio-reactors. Heat and mass transfer. Bioremediation of wastes. design of anaerobic and aerobic systems. Energy from biological systems. Monitoring and control of biological systems. Application of computer to biological processes.', '["Course Contents Definitions","Modelling and design of fermentation systems","Microbial growth kinetics","Design of bio-reactors","Heat and mass transfer","Bioremediation of wastes","design of anaerobic and aerobic systems","Energy from biological systems"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ABE 308', 'Rural Infrastructural Engineering', '300 Level', 'second', 2, true, 'Concept of integrated rural development (planning and implementation). Overview of the problems of rural infrastructures. Review of agricultural construction survey. Rural road', '["Concept of integrated rural development (planning and implementation)","Overview of the problems of rural infrastructures","Review of agricultural construction survey","Rural road"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ABE 401', 'Instrumentation and Measurement in Agricultural and Biosystems Engineering', '400 Level', 'first', 2, false, '', '[]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'GET 402', 'Engineering Project I', '400 Level', 'second', 2, false, '', '[]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'GET 404', 'Engineering Valuation and Costing', '400 Level', 'second', 2, false, '', '[]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'GET 501', 'Engineering Project Management', '500 Level', 'first', 3, false, 'Project management fundamentals - definitions, project environment, nature and characteristics, development practice, management by objectives, and the centrality of engineering to projects, infrastructures, national and global development. The scope of project management - organisational, financial, planning and control, personnel management, labour and public relations, wages and salary administration and resource management. Identification of project stakeholders; beneficiaries and impacted persons - functions, roles, responsibilities. Project community relations, communication and change management. Project planning, control and timeliness;decision making, forecasting, scheduling, work breakdown structure (WBS), deliverables and timelines, logical frameworks (log frames), risk analysis, role of subject matter experts (SMEs), role conflicts; Gantt Chart, CPM and PERT. Optimisation, linear programming as an aid to decision making, transport and materials handling. Monitoring and Evaluation - key performance indices (KPIs); methods of economic and technical evaluation. Industrial psychology, ergonomics/human factors and environmental impact considerations in engineering project design and management. Project business case - financial, technical and sustainability considerations. Case studies, site visits and invited industry professional seminars. General principles of management and appraisal techniques. Breakthrough and control management theory; production and maintenance management. Training and manpower development. The manager and policy formulation, objective setting, planning, organising and controlling, motivation and appraisal of results.', '["Project management fundamentals - definitions, project environment, nature and characteristics,...","The scope of project management - organisational, financial, planning and control, personnel management,...","Identification of project stakeholders","beneficiaries and impacted persons - functions, roles, responsibilities","Project community relations, communication and change management","Project planning, control and timeliness;decision making, forecasting, scheduling, work breakdown...","Gantt Chart, CPM and PERT","Optimisation, linear programming as an aid to decision making, transport and materials handling"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'GET 502', 'Engineering Law', '500 Level', 'second', 2, false, 'Common Law: its history, definition, nature and division. Legislation, codification interpretation. Equity: definition and its main spheres. Law of contracts for Engineers: Forms of contract and criteria for selecting contractors; offer, acceptance, communication termination of contract. Terms of Contracts; suppliers'' duties - Damages and other Remedies. Termination/cancellation of contract Liquidation and Penalties; exemption clauses, safety and risk. Health and Safety. Duties of employers towards their employees. Duties imposed on employees. Fire precautions act. Design for safety. General principles of criminal law. Law of', '["Common Law: its history, definition, nature and division","Legislation, codification interpretation","Equity: definition and its main spheres","Law of contracts for Engineers: Forms of contract and criteria for selecting contractors","offer, acceptance, communication termination of contract","Terms of Contracts","suppliers'' duties - Damages and other Remedies","Termination/cancellation of contract Liquidation and Penalties"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ABE 501', 'Environmental and Social Impact Analysis', '500 Level', 'first', 2, false, 'Concept of environmental and social consequences/dimensions of development projects. Methods of impact analysis. Physical, sociological, legal, economic, environmental and public health implications of human activities. Effects of changed environments on man. Examples of impact assessment with particular reference to developing countries. Role of environmental engineering in preventing or reducing environmental stress. Environmental and social management plans (ESMP); Planning and policy, administration and organisation of natural resources development and public health. Land use planning and landscape design. Monitoring and evaluation of projects for ESIA compliance. Practical content: Students are expected to undertake an environmental and social impact analysis of an on- going project on campus.', '["Concept of environmental and social consequences/dimensions of development projects","Methods of impact analysis","Physical, sociological, legal, economic, environmental and public health implications of human activities","Effects of changed environments on man","Examples of impact assessment with particular reference to developing countries","Role of environmental engineering in preventing or reducing environmental stress","Environmental and social management plans (ESMP)","Planning and policy, administration and organisation of natural resources development and public health"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ABE 502', 'Aquaculture and Agroponics Engineering', '500 Level', 'second', 2, false, 'Aquaculture: Types of fish ponds. Design and construction of fish ponds. Integrated fish farming. Water quality for fish farming. Water conservation. Machinery for fish farms. Pollution control. Ecological re-use and disposal of water. Product harvesting, sorting and processing. Design of fish kilns. Agroponics: Agroponic farming systems. Prospects of agroponic agriculture in Nigeria. Soil and water management in agroponic systems. Economics of agroponic systems. Modern aquaponics and hydroponics systems design and use. Practical content: Each student is expected to plant a yam seedling in a bag of sand and monitor its growth until harvest during the semester. Excursion: Visit to a commercial fish farm site or the university fish farm.', '["Aquaculture: Types of fish ponds","Design and construction of fish ponds","Integrated fish farming","Water quality for fish farming","Water conservation","Machinery for fish farms","Pollution control","Ecological re-use and disposal of water"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ABE 503', 'Livestock Production Engineering', '500 Level', 'first', 2, false, 'Production systems: rearing, fattening and milk production systems. Rearing systems: objectives; nomadic, transhumant, sedentary, scavenging and industrial (ranching) - organisation, personnel and infrastructures. Design, construction and equipment for housing for pigs, sheep, goats, domestic fowls, cattle and dairy cattle. Fattening production systems: Grass and intensive fattening. Milk production systems: factors limiting tropical milk production; milking bail; milking parlour: selection, design and types. Environmental requirements for animals. Environmental impact on animal growth and reproduction on their general physiology. Assessment of thermal comfort. Parametres affecting thermal comfort of animals. ASHRAE comfort charts. Ventilation systems: natural and automated. Aerodynamics of animal buildings. Building design methodology. Integrating animals with their environment through building designs. Disease control: Causes, factors favouring transmission. Design of buildings to control diseases. Animal waste management: Characteristics of animal wastes. Objectives of waste treatment; aerobic and anaerobic treatment of waste; manure disposal equipment. Excursion: Visit to a functional biogas plant.', '["Production systems: rearing, fattening and milk production systems","Rearing systems: objectives","nomadic, transhumant, sedentary, scavenging and industrial (ranching) - organisation, personnel and...","Design, construction and equipment for housing for pigs, sheep, goats, domestic fowls, cattle and dairy cattle","Fattening production systems: Grass and intensive fattening","Milk production systems: factors limiting tropical milk production","milking bail","milking parlour: selection, design and types"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ABE 504', 'Greenhouse Technology', '500 Level', 'second', 2, false, 'Definition of greenhouse. Meaning of greenhouse technology and controlled environment agriculture (CEA). History and present scenario of greenhouse cultivation. Importance of greenhouse crop cultivation. Types of greenhouses. Types of covering materials and thermal screens for greenhouses. Planning of greenhouses. Importance of different climatic and non-climatic factors in selecting proper greenhouse technology. Measuring systems required for greenhouse. Design, construction and cost estimate of a greenhouse. The bamboo greenhouse technology. Control mechanisms for different climatic conditions: light, temperature, humidity, precipitation and carbon dioxide. Special methods of crop husbandry in greenhouse cultivation. Excursion: Visit to a commercial farm with greenhouse facility.', '["Definition of greenhouse","Meaning of greenhouse technology and controlled environment agriculture (CEA)","History and present scenario of greenhouse cultivation","Importance of greenhouse crop cultivation","Types of greenhouses","Types of covering materials and thermal screens for greenhouses","Planning of greenhouses","Importance of different climatic and non-climatic factors in selecting proper greenhouse technology"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ABE 505', 'Drone and Robot Technology in Agriculture', '500 Level', 'first', 2, false, 'Automation: Introduction to automation. Control systems: open-loop and closed-loop, feedback control, logic control, on-off control and linear control systems. Control actions: discrete control (on/off); PID controller; sequential control and logical sequence or system state control; computer control. Automation tools: artificial neural network (ANN); distributed control system (DCS); human machine interface (HMI); robotic process automation (RPA); supervisory control and data acquisition (SCADA); programmable logic controller (PLC); instrumentation; motion control; robotics. Programming languages: introduction to programming language; Matlab programming, R programming, C, C# and C++ programming, Java and Java Script programming and Python programming. Sensors and actuators: introduction to sensors, types and applications. Design and selection of sensors. Introduction to actuators, types and applications. Design and selection of actuators. Drones or Unmanned Aerial Vehicles (UAVs): Introduction, types and classification of drones. Architecture (components) of a drone: flight controller; electronic speed controller (ESC); battery; radio transmitter/receiver; antenna; propellers; electric motor; camera and its accessories.; ground station; intelligent sensors; intelligent battery; GNSS and RTK module. Advantages and disadvantages of drones. Design and selection of drones. Working principles of a drone. Performance considerations criteria of a drone. Application of drones in agriculture. Robots: Introduction, types and characteristics of agricultural robots (Agribot). Primary areas of robotics: operator interface; mobility or locomotion; manipulators and effectors; programming; sensing and perception. Advantages and disadvantages of robots. Robot design process. Design of components of agricultural robots: end effectors; grippers; manipulators. Operating principles of an agricultural robot. Performance evaluation of robots: productive time, overhead time and working efficiency index. Accuracy and repeatability of a robot. Application of robot to agriculture.', '["Automation: Introduction to automation","Control systems: open-loop and closed-loop, feedback control, logic control, on-off control and linear...","Control actions: discrete control (on/off)","PID controller","sequential control and logical sequence or system state control","computer control","Automation tools: artificial neural network (ANN)","distributed control system (DCS)"]'::jsonb),
  ('Agricultural and Bioresources Engineering', 'ABE 599', 'Final Year Project', '500 Level', 'first', 4, false, 'Individual student project to deepen knowledge, strengthen practical experience and encourage creativity and independent work. The project ends in a comprehensive written report.', '["Individual student project to deepen knowledge, strengthen practical experience and encourage creativity...","The project ends in a comprehensive written report"]'::jsonb),
  ('Biomedical Engineering', 'GET 101', 'Engineer in Society', '100 Level', 'first', 1, false, 'History, evolution and philosophy of science. engineering and technology. The engineering profession - engineering family (engineers, technologists, technicians and craftsmen), professional bodies and societies. Engineers'' code of conduct and ethics, and engineering literacy. Sustainable development goals (SDGs), innovation, infrastructures and nation building - economy, politics, business. Safety and risk analysis in engineering practice. Engineering competency skills - curriculum overview, technical, soft and digital skills. Guest seminars and invited lectures from different engineering professional associations.', '["History, evolution and philosophy of science","engineering and technology","The engineering profession - engineering family (engineers, technologists, technicians and craftsmen),...","Engineers'' code of conduct and ethics, and engineering literacy","Sustainable development goals (SDGs), innovation, infrastructures and nation building - economy, politics,...","Safety and risk analysis in engineering practice","Engineering competency skills - curriculum overview, technical, soft and digital skills","Guest seminars and invited lectures from different engineering professional associations"]'::jsonb),
  ('Biomedical Engineering', 'GET 102', 'Engineering Graphics and Solid Modelling', '100 Level', 'second', 2, false, 'Introduction to design thinking and engineering graphics. First and third angle orthogonal projections. Isometric projections; sectioning, conventional practices, conic sections and development. Freehand and guided sketching - pictorial and orthographic. Visualisation and solid modelling in design, prototyping and product-making. User interfaces in concrete terms. Design, drawing, animation, rendering and simulation workspaces. Sketching of 3D objects. Viewports and sectioning to shop drawings in orthographic projections and perspectives. Automated viewports. Sheet metal and surface modelling. Material selection and rendering. This course will use latest professional design tools such as fusion 360, solid works, solid edge or equivalent.', '["Introduction to design thinking and engineering graphics","First and third angle orthogonal projections","Isometric projections","sectioning, conventional practices, conic sections and development","Freehand and guided sketching - pictorial and orthographic","Visualisation and solid modelling in design, prototyping and product-making","User interfaces in concrete terms","Design, drawing, animation, rendering and simulation workspaces"]'::jsonb),
  ('Biomedical Engineering', 'BME 102', 'Introduction to Biomedical engineering', '100 Level', 'second', 2, false, '', '[]'::jsonb),
  ('Biomedical Engineering', 'ENT 211', 'Entrepreneurship and Innovation', '200 Level', 'first', 2, false, 'The concept of entrepreneurship (entrepreneurship, intrapreneurship/corporate entrepreneurship); theories, rationale and relevance of entrepreneurship (Schumpeterian and other perspectives, risk-taking, necessity and opportunity-based entrepreneurship, and creative destruction); characteristics of entrepreneurs (opportunity seeker, risk-taker, natural and nurtured, problem solver and change agent, innovator and creative thinker); entrepreneurial thinking (critical thinking, reflective thinking and creative thinking). Innovation (The concept of innovation, dimensions of innovation, change and innovation, knowledge and innovation). Enterprise formation, partnership and networking (basics of business plan, forms of business ownership, business registration and alliance formation, and joint ventures). Contemporary entrepreneurship issues (knowledge, skills and technology, intellectual property, virtual office and networking). Entrepreneurship in Nigeria (biography of inspirational entrepreneurs, youth and women entrepreneurship, entrepreneurship support institutions, youth enterprise networks and environmental and cultural barriers to entrepreneurship). Basic principles of e-commerce.', '["The concept of entrepreneurship (entrepreneurship, intrapreneurship/corporate entrepreneurship)","theories, rationale and relevance of entrepreneurship (Schumpeterian and other perspectives, risk-taking,...","characteristics of entrepreneurs (opportunity seeker, risk-taker, natural and nurtured, problem solver and...","entrepreneurial thinking (critical thinking, reflective thinking and creative thinking)","Innovation (The concept of innovation, dimensions of innovation, change and innovation, knowledge and...","Enterprise formation, partnership and networking (basics of business plan, forms of business ownership,...","Contemporary entrepreneurship issues (knowledge, skills and technology, intellectual property, virtual...","Entrepreneurship in Nigeria (biography of inspirational entrepreneurs, youth and women entrepreneurship,..."]'::jsonb),
  ('Biomedical Engineering', 'GET 201', 'Applied Electricity I', '200 Level', 'first', 3, false, 'Fundamental concepts: Electric fields, charges, magnetic fields. current, B-H curves Kirchhoff''s laws, superposition. Thevenin, Norton theorems, Reciprocity, RL, RC, RLC circuits. DC, AC bridges, Resistance, Capacitance, Inductance measurement, Transducers, Single phase circuits, Complex j - notation, AC circuits, impedance, admittance, susceptance.', '["Fundamental concepts: Electric fields, charges, magnetic fields","current, B-H curves Kirchhoff''s laws, superposition","Thevenin, Norton theorems, Reciprocity, RL, RC, RLC circuits","DC, AC bridges, Resistance, Capacitance, Inductance measurement, Transducers, Single phase circuits,..."]'::jsonb),
  ('Biomedical Engineering', 'GET 202', 'Engineering Materials', '200 Level', 'second', 3, false, 'Basic material science; atomic structure, atomic bonding and crystal structures. Engineering materials situating metals and alloys; metals and alloys, classifications of metals, metal extraction processes using iron and steel (ferrous) and aluminium (nonferrous) as examples, phase diagrams/iron carbon diagrams, and mechanical workings of metals. Selection and applications of metals and alloys for specific applications in oil, aerospace, construction, manufacturing and transportation industries, among others. Ceramics (including glass); definition, properties, structure and classifications of ceramics. Bioactive and glass - ceramics. Toughing mechanism for ceramics. Polymers; definition of polymers as engineering materials, chemistry of polymeric materials, polymer crystallisation, polymer degradation and aging. Thermoplastic and thermosetting polymers and concepts of copolymers and homopolymers. Composites; definition, classification, characterisation, properties and composite. Applications of composites. Nanomaterials; definition, classification and applications of nanomaterials as emerging technology. Processing of nanomaterials including mechanical grinding, wet chemical synthesis, gas phase synthesis, sputtered plasma processing, microwave plasma processing and laser ablation. Integrity assessment of engineering materials; effect of engineering design, engineering materials processing, selection, manufacturing and assembling on the performance and service life of engineering materials. Metallography and fractography of materials. Mechanical testing (destructive testing) of materials such as', '["Basic material science","atomic structure, atomic bonding and crystal structures","Engineering materials situating metals and alloys","metals and alloys, classifications of metals, metal extraction processes using iron and steel (ferrous)...","Selection and applications of metals and alloys for specific applications in oil, aerospace, construction,...","Ceramics (including glass)","definition, properties, structure and classifications of ceramics","Bioactive and glass - ceramics"]'::jsonb),
  ('Biomedical Engineering', 'GET 204', 'Students Workshop Practice', '200 Level', 'second', 2, false, 'The course comprises general, mechanical and electrical components: supervised hands-on experience in safe usage of tools and machines for selected tasks; Use of measuring instruments (calipers, micrometers, gauges, sine bar, wood planners, saws, sanders, and pattern making). Machine shop: lathe work shaping, milling, grinding, reaming, metal spinning. Hand tools, gas and arc welding, cutting, brazing and soldering. Foundry practice.Industrial safety and accident prevention, ergonomics, metrology. Casting processes. Metal forming processes: hot-working and cold-working processes (forging, press- tool work, spinning, etc.). Metal joining processes(welding, brazing and soldering). Heat treatment. Material removal processes. machine tools and classification. Simple theory of metal cutting. Tool action and cutting forces. Introduction to CNC machines. Supervised identification, use and care of various electrical and electronic components such as resistors, inductors, capacitors, diodes and transistors. Exposure to different electric circuits, wiring schemes, analogue and digital electrical and electronic measurements. Household and industrial energy consumption measurements. Practical energy conservation principles.', '["The course comprises general, mechanical and electrical components: supervised hands-on experience in safe...","Use of measuring instruments (calipers, micrometers, gauges, sine bar, wood planners, saws, sanders, and...","Machine shop: lathe work shaping, milling, grinding, reaming, metal spinning","Hand tools, gas and arc welding, cutting, brazing and soldering","Foundry practice.Industrial safety and accident prevention, ergonomics, metrology","Casting processes","Metal forming processes: hot-working and cold-working processes (forging, press- tool work, spinning, etc.)","Metal joining processes(welding, brazing and soldering)"]'::jsonb),
  ('Biomedical Engineering', 'GET 209', 'Engineering Mathematics I', '200 Level', 'first', 3, false, 'Limits, continuity, differentiation, introduction to linear first order differential equations, partial and total derivatives, composite functions, matrices and determinants, vector algebra, vector calculus, directional derivatives.', '["Limits, continuity, differentiation, introduction to linear first order differential equations, partial..."]'::jsonb),
  ('Biomedical Engineering', 'GET 211', 'Computer and Software Engineering', '200 Level', 'first', 3, false, 'Introduction to computers and computing; computer organisation - data processing, memory, registers and addressing schemes; Boolean algebra; floating-point arithmetic; representation of non-numeric information; problem-solving and algorithm development; coding (solution design using flowcharts and pseudo codes). Data models and data structures; computer software and operating system; computer operators and operators precedence; components of computer programs; introduction to object oriented, structured and visual programming; use of MATLAB in engineering applications. ICT fundamentals, Internet of Things (IoT). Elements of software engineering.', '["Introduction to computers and computing","computer organisation - data processing, memory, registers and addressing schemes","Boolean algebra","floating-point arithmetic","representation of non-numeric information","problem-solving and algorithm development","coding (solution design using flowcharts and pseudo codes)","Data models and data structures"]'::jsonb),
  ('Biomedical Engineering', 'BME 214', 'General Biochemistry I', '200 Level', 'second', 2, false, 'Review of general chemistry: chemical elements and the periodic table; electronic configuration, electronic orbital, valency of atoms, and types of chemical bonds; metals and non-metals; acids and bases, highlighting Lewis Conception; carbon, sp3 hybridization, the tetrahedron and covalent bond; functional groups; water and its special properties. Introduction of the cell and hierarchy of organisation of living things: macromolecules, organelles, cells, tissues; organs, systems and organism. Amino acids, proteins; the peptide bond and polypeptides; proteins as biological catalysts, immune agents and structural molecules. Carbohydrates; the glycosidic bond; relationship of photosynthesis and tissue respiration; carbohydrate as storage molecule of easily accessible metabolic energy. Fatty acids and lipids: the ester bond of lipids and triglycerides; fat as efficient energy storage molecule. Nucleic acids and nucleotides: DNA and RNA as polymers of nucleotides; the phosphodiester bond; gene and genetic information transcription and translation.', '["Review of general chemistry: chemical elements and the periodic table","electronic configuration, electronic orbital, valency of atoms, and types of chemical bonds","metals and non-metals","acids and bases, highlighting Lewis Conception","carbon, sp3 hybridization, the tetrahedron and covalent bond","functional groups","water and its special properties","Introduction of the cell and hierarchy of organisation of living things: macromolecules, organelles,..."]'::jsonb),
  ('Biomedical Engineering', 'BME 215', 'Human Genetic I', '200 Level', 'first', 2, false, 'Human Heredity: haploid and diploid chromosome, DNA, trait, genes, blood group. The Human Genome: Definition of Genome; History of Human Genome Project; Gene Sequencing; Molecular organization and gene content; Genetic Coding Genomic variation in humans. Genetic disorders: Albinism, Cystic Fibrosis, Dwarfism, Sickle Cell Disease, Color Blindness, Hemophilia, Duschenne Muscular dystrophy. 300 Level', '["Human Heredity: haploid and diploid chromosome, DNA, trait, genes, blood group","The Human Genome: Definition of Genome","History of Human Genome Project","Gene Sequencing","Molecular organization and gene content","Genetic Coding Genomic variation in humans","Genetic disorders: Albinism, Cystic Fibrosis, Dwarfism, Sickle Cell Disease, Color Blindness, Hemophilia,...","300 Level"]'::jsonb),
  ('Biomedical Engineering', 'BME 211', 'Human Anatomy I', '200 Level', 'first', 2, false, 'An overview of cell biology; tissue structures and human histology; basic structure of the human body; body planes and positions; the skeleton; regional anatomy of the upper limb, lower limb, thorax and abdomen.', '["An overview of cell biology","tissue structures and human histology","basic structure of the human body","body planes and positions","the skeleton","regional anatomy of the upper limb, lower limb, thorax and abdomen"]'::jsonb),
  ('Biomedical Engineering', 'BME 213', 'Human Physiology I', '200 Level', 'first', 2, false, 'Basic concepts in Human physiology; cellular physiology; homeostasis; musculoskeletal system; Cardiovascular System; Respiratory System; Urinary System.', '["Basic concepts in Human physiology","cellular physiology","homeostasis","musculoskeletal system","Cardiovascular System","Respiratory System","Urinary System"]'::jsonb),
  ('Biomedical Engineering', 'ENT 312', 'Venture Creation', '300 Level', 'second', 2, false, 'Opportunity identification (sources of business opportunities in Nigeria, environmental scanning, demand and supply gap/unmet needs/market gaps/market research, unutilised resources, social and climate conditions and technology adoption gap). business development (business planning, market research). Entrepreneurial finance (venture capital, equity finance, micro-finance, personal savings, small business investment organizations and business plan competition). Entrepreneurial marketing and e-commerce (principles of marketing, customer acquisition & retention, B2B, C2C and B2C models of e-commerce, First Mover Advantage, E-commerce business models and successful e-commerce companies). Small business management/family business: Leadership & Management, basic book keeping, nature of family business and family business growth model. Negotiation and business communication (strategy and tactics of negotiation/bargaining, traditional and modern business communication methods). Opportunity discovery demonstrations (business idea generation presentations, business idea contest, brainstorming sessions, idea pitching). Technological solutions (The concept of market/customer solution, customer solution and emerging technologies, business applications of new technologies - artificial intelligence (AI), virtual/mixed reality (VR), Internet of things (IoTs), blockchain, cloud computing, renewable energy, etc. Digital business and e-commerce strategies).', '["Opportunity identification (sources of business opportunities in Nigeria, environmental scanning, demand...","business development (business planning, market research)","Entrepreneurial finance (venture capital, equity finance, micro-finance, personal savings, small business...","Entrepreneurial marketing and e-commerce (principles of marketing, customer acquisition & retention, B2B,...","Small business management/family business: Leadership & Management, basic book keeping, nature of family...","Negotiation and business communication (strategy and tactics of negotiation/bargaining, traditional and...","Opportunity discovery demonstrations (business idea generation presentations, business idea contest,...","Technological solutions (The concept of market/customer solution, customer solution and emerging..."]'::jsonb),
  ('Biomedical Engineering', 'GET 304', 'Technical Writing and Communication', '300 Level', 'second', 3, false, 'A brief review of common pitfalls in writing. Principles of clear writing (punctuations and capitalization). Figures of speech. Units of grammar. Tenses and verb agreement. Active and passive sentences Lexis, structure Fog and Index concept. Skills for communication and communication algorithm. Types and goals of communication; Interpersonal communication; features and the Finger Model or A,B,C,D,E of good interpersonal communication (accuracy of technical terms, brevity of expression, clarity of purpose, directness of focus and effectiveness of the report). Language and organisation of reports. Technical report writing skills(steps, problems in writing, distinguishing technical and other reports, significance, format and styles of writing technical reports). Different formats for communication; styles of correspondences - business report and proposal, business letter, memorandum, e-mails, etc. Proposals for projects and research; format, major steps and tips of grant-oriented proposals. Research reports(competency, major steps, components and formats of research reports and', '["A brief review of common pitfalls in writing","Principles of clear writing (punctuations and capitalization)","Figures of speech","Units of grammar","Tenses and verb agreement","Active and passive sentences Lexis, structure Fog and Index concept","Skills for communication and communication algorithm","Types and goals of communication"]'::jsonb),
  ('Biomedical Engineering', 'GET 305', 'Engineering Statistics and Data Analysis', '300 Level', 'first', 3, false, 'Descriptive statistics, frequency distribution, populations and sample, central tendency, variance data sampling, mean, median, mode, mean deviation, percentiles, etc. Probability. Binomial, Poisson hyper-geometric, normal distributions, etc. Statistical inference intervals, test hypothesis and significance. Regression and correlation. Introduction to big data analytics and cloud computing applications. Introduction to the R language; R as a calculator; Vectors, matrices, factors, data frames and other R collections. Iteration and looping control structures. Conditionals and other controls. Designing, using and extending functions. The Apply Family. Statistical modelling and inference in R. .GET 306: Renewable Energy Systems and Technology (3 Units C: LH 30; PH 45) Learning Outcomes At the end of the course, the students should be able to: 1. identify the types, uses and advantages of renewable energy in relation to climate change; 2. design for use the various renewable energy systems; 3. recognise and analyse the current energy systems in Nigeria, their impacts on development and the global energy demand and supply scenarios; 4. appreciate the environmental impact of energy exploitation and utilisation, and pursue the sustainable development of renewable energy for various applications; and 5. recognise the exploitation, excavation, production, and processing of fossil fuels such as coal, petroleum and natural gas, and discuss the sources, technology and contribution to future energy demands of renewable energy.', '["Descriptive statistics, frequency distribution, populations and sample, central tendency, variance data...","Probability","Binomial, Poisson hyper-geometric, normal distributions, etc","Statistical inference intervals, test hypothesis and significance","Regression and correlation","Introduction to big data analytics and cloud computing applications","Introduction to the R language","R as a calculator"]'::jsonb),
  ('Biomedical Engineering', 'GET 306', 'Renewable Energy Systems and Technology', '300 Level', 'second', 3, false, 'Current and potential future energy systems in Nigeria and globally - resources, extraction, concepts in energy conversion systems; parallels and differences in various conversion systems and end-use technologies, with emphasis on meeting 21st-century national, regional and global energy needs in a sustainable manner. Various energy technologies in each fuel cycle stage for fossil (oil, gas, synthetic), nuclear (fission and fusion) and renewable (solar, biomass, wind, hydro, and geothermal). Energy types, storage, transmission and conservation. Analysis of energy mixes within an engineering, economic and social context. Sustainable energy; emphasise sustainability in general and in the overall concept of sustainable development and the link this has with sustainable energy as the fundamental benefit of renewable energy. Practical Contents Simple measurement of solar radiation, bomb calorimeter determination of calorific value of fuels and biomass; measurement of the velocity of wind, waves and the energy that abound in them; laboratory production of biogas and determination of energy available in it; simple conversion of solar energy to electricity; transesterification of edible oil into biodiesel; simulation of geothermal energy; Geiger-Muller or Scintillation Counters'' determination of uranium or thorium energy; simple solid or salt storage of energy; hybrid application of renewable energy.', '["Current and potential future energy systems in Nigeria and globally - resources, extraction, concepts in...","parallels and differences in various conversion systems and end-use technologies, with emphasis on meeting...","Various energy technologies in each fuel cycle stage for fossil (oil, gas, synthetic), nuclear (fission...","Energy types, storage, transmission and conservation","Analysis of energy mixes within an engineering, economic and social context","Sustainable energy","emphasise sustainability in general and in the overall concept of sustainable development and the link...","Practical Contents Simple measurement of solar radiation, bomb calorimeter determination of calorific..."]'::jsonb),
  ('Biomedical Engineering', 'GET 307', 'Introduction to Artificial Intelligence, Machine Language and Convergent Technologies', '300 Level', 'first', 3, false, '', '[]'::jsonb),
  ('Biomedical Engineering', 'BME 334', 'Biomedical Instrumentation', '300 Level', 'second', 2, false, 'Introduction to biomedical instrumentation: basic biomedical instrumentation system. General considerations in the design of biomedical instrumentation systems. Biomedical measurements: errors in measurement. Biological signals: bioelectric signals. Biomedical sensors and transducers-types and forms. Physiological measurements: audiology; cardiac physiology; gastrointestinal tract physiology; neurophysiology; ophthalmic and vision science; respiratory physiology; urodynamic physiology; vascular technology; blood pressure measurement; blood flow measurements; measurement of the respiratory system; ECG measurement systems. Clinical laboratory instrumentation. Electrical safety in instrumentation. Introduction to Biomedical signal processing.', '["Introduction to biomedical instrumentation: basic biomedical instrumentation system","General considerations in the design of biomedical instrumentation systems","Biomedical measurements: errors in measurement","Biological signals: bioelectric signals","Biomedical sensors and transducers-types and forms","Physiological measurements: audiology","cardiac physiology","gastrointestinal tract physiology"]'::jsonb),
  ('Biomedical Engineering', 'BME 351', 'Biomaterials Engineering', '300 Level', 'first', 2, false, 'Introduction to Engineering properties of biomaterials: fatigue of biomaterials applications of materials in medicine-cardiovascular, surgical, dental, ophthalmologic, orthopaedic applications. Bioelectrodes and bio (medical) sensors. Artificial organs: heart, teeth, limbs and kidney. Compatibility of biomaterials: tissue-material interactions; host response to biomaterials; biomaterials failure. 400 Level GET 402 Engineering Project I (2 Units C: PH 90) Learning Outcomes At the end of this course, the students should be able to: 1. complete the design phase of a complex engineering problem sourced from industry or community during the SIWES III programme; amd 2. demonstrate the connection between engineering product-making and the theoretical courses they have learned following the applicable industry best practices. Course Contents', '["Introduction to Engineering properties of biomaterials: fatigue of biomaterials applications of materials...","Bioelectrodes and bio (medical) sensors","Artificial organs: heart, teeth, limbs and kidney","Compatibility of biomaterials: tissue-material interactions","host response to biomaterials","biomaterials failure","400 Level GET 402 Engineering Project I (2 Units C: PH 90) Learning Outcomes At the end of this course,...","complete the design phase of a complex engineering problem sourced from industry or community during the..."]'::jsonb),
  ('Biomedical Engineering', 'BME 332', 'Biomedical Electronics', '300 Level', 'second', 2, false, 'General overview of biomedical electronics; history of biomedical electronics; biomedical electronics as composing of bioelectronics and medical electronics; intersection areas in biomedical electronics. Introduction to bioelectronics. Introduction to medical electronics. Study of common biomedical electronic equipment and systems such as thermometers, stethoscopes, pulse oximeters, patient monitors, telemetry systems, ambulatory systems. Hazards of electro-medical devices: physiological effects of electricity; tests and safety checks of medical devices; electrical safety testing. Troubleshooting of electro-medical equipment. Design of biomedical circuits. Computer applications in biology and medicine.', '["General overview of biomedical electronics","history of biomedical electronics","biomedical electronics as composing of bioelectronics and medical electronics","intersection areas in biomedical electronics","Introduction to bioelectronics","Introduction to medical electronics","Study of common biomedical electronic equipment and systems such as thermometers, stethoscopes, pulse...","Hazards of electro-medical devices: physiological effects of electricity"]'::jsonb),
  ('Biomedical Engineering', 'BME 316', 'General Pharmacology', '300 Level', 'second', 2, false, 'General Pharmacology: Historical development of pharmacology; divisions of pharmacology and their applications; definitions of terms and abbreviations: concept and nature of drugs. Pharmacodynamics; pharmacokinetics; classification of drugs and their importance. Drug abuse and control; drug noncompliance or misuse. Toxicology: Introduction to toxicology and its importance; general principles of poison managements.', '["General Pharmacology: Historical development of pharmacology","divisions of pharmacology and their applications","definitions of terms and abbreviations: concept and nature of drugs","Pharmacodynamics","pharmacokinetics","classification of drugs and their importance","Drug abuse and control","drug noncompliance or misuse"]'::jsonb),
  ('Biomedical Engineering', 'GET 402', 'Engineering Project I', '400 Level', 'second', 2, false, '', '[]'::jsonb),
  ('Biomedical Engineering', 'GET 404', 'Engineering Valuation and Costing', '400 Level', 'second', 2, false, '', '[]'::jsonb),
  ('Biomedical Engineering', 'BME 401', 'Biomedical Systems Analysis', '400 Level', 'first', 2, false, 'Advanced mathematical concepts: linear relations and functions; systems of equations and inequalities; polar coordinates and complex numbers; exponential and logarithmic functions; iteration; statistics and data Analysis; limits, derivatives and integrals: applications of differentiation and integration. Mathematical methods and Models: numerical methods; finite differences; solutions of differential equations; role and application of models in biology and medicine. Computer simulations: Development of computer simulation techniques to study physiological system.', '["Advanced mathematical concepts: linear relations and functions","systems of equations and inequalities","polar coordinates and complex numbers","exponential and logarithmic functions","iteration","statistics and data Analysis","limits, derivatives and integrals: applications of differentiation and integration","Mathematical methods and Models: numerical methods"]'::jsonb),
  ('Biomedical Engineering', 'BME 435', 'Biomedical Informatics', '400 Level', 'first', 2, false, 'Introduction to biomedical informatics; components of biomedical informatics. Bioinformatics: What is bioinformatics; components of bioinformatics; biological data; information complexity; bioinformatics applications? Medical informatics: Management Information Systems in biology and medicine-data acquisition, data storage and retrieval, data processing; components of Health Information Systems; types of Health Information Systems. Computer networking in the hospitals: the concept of computer networking, telemetry; e-Health. Software development in biology and medicine. Computer applications in medical diagnosis and therapy. Computer-aided simulation and experimentation.', '["Introduction to biomedical informatics","components of biomedical informatics","Bioinformatics: What is bioinformatics","components of bioinformatics","biological data","information complexity","bioinformatics applications? Medical informatics: Management Information Systems in biology and...","components of Health Information Systems"]'::jsonb),
  ('Biomedical Engineering', 'BME 453', 'Human Biotechnology', '400 Level', 'first', 2, false, 'Introduction to Biotechnology: Historical background; types, their examples and applications Biotechnology and human health: pharmaceuticals, diagnosis, vaccines, gene therapy, organ replacement therapy, nutrition, environmental health, health prevention, etc. Introduction to Genetic Engineering: history of genetic engineering; cloning; DNA fingerprinting; polymerase chain reaction; summary of DNA fingerprinting; application of GE in fighting diseases. Introduction to Tissue Engineering: basic biological concept- cells, organelles; tissue organisation; tissue dynamics, representative tissue; case studies; barriers to tissue engineering adoptions.', '["Introduction to Biotechnology: Historical background","types, their examples and applications Biotechnology and human health: pharmaceuticals, diagnosis,...","Introduction to Genetic Engineering: history of genetic engineering","DNA fingerprinting","polymerase chain reaction","summary of DNA fingerprinting","application of GE in fighting diseases","Introduction to Tissue Engineering: basic biological concept- cells, organelles"]'::jsonb),
  ('Biomedical Engineering', 'BME 461', 'Clinical Engineering', '400 Level', 'first', 2, false, 'Evolution of clinical engineering. The health care environment. Equipment planning. Clinical engineering education. Quality assurance. Equipment replacement project. The role of clinical engineering in hospital organisation and enhancing patient''s safety. Healthcare facilities planning; A model clinical engineering department; careers, roles, and responsibilities of clinical engineers.', '["Evolution of clinical engineering","The health care environment","Equipment planning","Clinical engineering education","Quality assurance","Equipment replacement project","The role of clinical engineering in hospital organisation and enhancing patient''s safety","Healthcare facilities planning"]'::jsonb),
  ('Biomedical Engineering', 'BME 481', 'Rehabilitation Engineering', '400 Level', 'first', 2, true, 'Introduction to rehabilitation engineering: technology and disability. Assistive technologies: implants, prostheses, and artificial organs in rehabilitation; Wheelchair and others. Rehabilitation robotics: aids for physically handicapped people. Rehabilitation in Special areas: Rehabilitation in Sports; Physiotherapeutic technologies; Psychiatric devices; orthopaedic devices, etc.', '["Introduction to rehabilitation engineering: technology and disability","Assistive technologies: implants, prostheses, and artificial organs in rehabilitation","Wheelchair and others","Rehabilitation robotics: aids for physically handicapped people","Rehabilitation in Special areas: Rehabilitation in Sports","Physiotherapeutic technologies","Psychiatric devices","orthopaedic devices, etc"]'::jsonb),
  ('Biomedical Engineering', 'GET 501', 'Engineering Project Management', '500 Level', 'first', 3, false, 'Project management fundamentals - definitions, project environment, nature and characteristics, development practice, management by objectives, and the centrality of engineering to projects, infrastructures, national and global development. The scope of project management - organisational, financial, planning and control, personnel management, labour and public relations, wages and salary administration and resource management. Identification of project stakeholders; beneficiaries and impacted persons - functions, roles, responsibilities. Project community relations, communication and change management. Project planning, control and timeliness;decision making, forecasting, scheduling, work breakdown structure (WBS), deliverables and timelines, logical frameworks (log frames), risk analysis, role of subject matter experts (SMEs), role conflicts; Gantt Chart, CPM and PERT. Optimisation, linear programming as an aid to decision making, transport and materials handling. Monitoring and Evaluation - key performance indices (KPIs); methods of economic and technical evaluation. Industrial psychology, ergonomics/human factors and environmental impact considerations in engineering project design and management. Project business case - financial, technical and sustainability considerations. Case studies, site visits and invited industry professional seminars. General principles of management and appraisal techniques. Breakthrough and control management theory; production and maintenance management. Training and manpower development. The manager and policy formulation, objective setting, planning, organising and controlling, motivation and appraisal of results.', '["Project management fundamentals - definitions, project environment, nature and characteristics,...","The scope of project management - organisational, financial, planning and control, personnel management,...","Identification of project stakeholders","beneficiaries and impacted persons - functions, roles, responsibilities","Project community relations, communication and change management","Project planning, control and timeliness;decision making, forecasting, scheduling, work breakdown...","Gantt Chart, CPM and PERT","Optimisation, linear programming as an aid to decision making, transport and materials handling"]'::jsonb),
  ('Biomedical Engineering', 'GET 502', 'Engineering Law', '500 Level', 'second', 2, false, 'Common Law: its history, definition, nature and division. Legislation, codification interpretation. Equity: definition and its main spheres. Law of contracts for Engineers: Forms of contract and criteria for selecting contractors; offer, acceptance, communication termination of contract. Terms of Contracts; suppliers'' duties - Damages and other Remedies. Termination/cancellation of contract Liquidation and Penalties; exemption clauses, safety and risk. Health and Safety. Duties of employers towards their employees. Duties imposed on employees. Fire precautions act. Design for safety. General principles of criminal law. Law of torts: definition, classification and liabilities. Patents: requirements, application, and infringement. Registered designs: application, requirements, types and infringement. Company law. Labour law and Industrial Law. Business registration.', '["Common Law: its history, definition, nature and division","Legislation, codification interpretation","Equity: definition and its main spheres","Law of contracts for Engineers: Forms of contract and criteria for selecting contractors","offer, acceptance, communication termination of contract","Terms of Contracts","suppliers'' duties - Damages and other Remedies","Termination/cancellation of contract Liquidation and Penalties"]'::jsonb),
  ('Biomedical Engineering', 'BME 521', 'Biomedical Engineering Design', '500 Level', 'first', 3, false, 'Overview of Engineering Design: classical steps in engineering design - identify the need, research the problem, develop possible solutions, select the most promising solution, construct a prototype, test and evaluate the prototype, communicate the design, and redesign. Biomedical Devices: Introduction to biomedical devices; overview of biomedical device design. Biomedical Engineering Design methodology: design tools; design (project) team management; the design process; project definition; project design specification; materials selection. Biomedical engineering manufacturing: prototyping in biomedical device design; testing and optimisation of biomedical design; product documentation; project presentation; manufacturing and quality control. Ethico-legal issues in Biomedical Engineering Design: intellectual property management; regulation of biomedical devices.', '["Overview of Engineering Design: classical steps in engineering design - identify the need, research the...","Biomedical Devices: Introduction to biomedical devices","overview of biomedical device design","Biomedical Engineering Design methodology: design tools","design (project) team management","the design process","project definition","project design specification"]'::jsonb),
  ('Biomedical Engineering', 'BME 526', 'Computer-Aided Design of Biomedical Systems', '500 Level', 'second', 3, false, 'Computer Aided Design (CAD): Introduction; basic principles of CAD; CAD hardware and software; the drawing tools; design management; introduction to 3-dimensional (3-D) design; 3D modeling; the printing and plotting process. Design of biomedical systems: Use of CAD in the design of medical equipment. Practical applications - Biomedical applications of CAD: applications in medical imaging; applications in medical diagnosis of various diseases e.g. lung diseases, breast cancer, stroke, sleep disorder, epilepsy, liver cancer, microcalcifications, and artery disease. Minimum Academic Standards Equipment The professional skills necessary to practise biomedical engineering can be acquired first and foremost from the training using institutional facilities designed and equipped to stimulate the practice of the profession. It should, therefore, be adequate in quality and quantity.The number of laboratories each department has will depend on the number of biomedical engineering specialty options offered. As an example:', '["Computer Aided Design (CAD): Introduction","basic principles of CAD","CAD hardware and software","the drawing tools","design management","introduction to 3-dimensional (3-D) design","3D modeling","the printing and plotting process"]'::jsonb),
  ('Biomedical Engineering', 'BME 522', 'Equipment Reliability and Safety Technology', '500 Level', 'second', 3, false, 'Equipment reliability: Manufacturing and quality control; equipment (project) reliability; equipment maintainability and availability. Equipment safety: Safety consideration in equipment design - reliable equipment earthing reduction of leakage current and operation at low voltage. Safe instrumentation: Physiological effects of electricity, shock hazards, electrical safety codes and standards, power distribution protection, electric system testing. Quality assurance in equipment design.', '["Equipment reliability: Manufacturing and quality control","equipment (project) reliability","equipment maintainability and availability","Equipment safety: Safety consideration in equipment design - reliable equipment earthing reduction of...","Safe instrumentation: Physiological effects of electricity, shock hazards, electrical safety codes and...","Quality assurance in equipment design"]'::jsonb),
  ('Biomedical Engineering', 'BME 523', 'Biomedical Imaging Systems', '500 Level', 'first', 3, false, 'Introduction to Radiation: review of physical concepts of radiation-atomic and nuclear structures, electromagnetic spectrum, x-ray production, radioactive decay; ionizing and non- ionizing radiation; X-ray interaction. Radiation & Imaging Systems: X-rays - characteristics and applications; computerized tomography; technology and applications; gamma camera; nuclear magnetic resonance imaging; systems and applications; ultrasound imaging. Basic radiobiology: radiation dosimetry and protection; Legislation and regulations for radiation protection.', '["Introduction to Radiation: review of physical concepts of radiation-atomic and nuclear structures,...","ionizing and non- ionizing radiation","X-ray interaction","Radiation & Imaging Systems: X-rays - characteristics and applications","computerized tomography","technology and applications","gamma camera","nuclear magnetic resonance imaging"]'::jsonb),
  ('Biomedical Engineering', 'BME 524', 'Biomedical Signal Processing', '500 Level', 'second', 3, false, 'Signals: What is a signal? History; categories; application fields. Biomedical Signals: nature, sources, types and examples. Signal Processing: Definition, Stochastic and deterministic signals, Discrete signals, Linear time invariant systems, Duality of time and frequency domain, Hypotheses testing. Biomedical signal Processing: Brain signals-local field potentials (LFP), electrocorticogram, (ECG), electroencephalogram (EEG), and magnetoencephalogram (MEG); Heart signals - Electrocardiogram, Heart rate variability, Fetal ECG; Electromyogram; Gastro- intestinal signals; Acoustic signals. Modeling Biomedical Systems.', '["Signals: What is a signal? History","categories","application fields","Biomedical Signals: nature, sources, types and examples","Signal Processing: Definition, Stochastic and deterministic signals, Discrete signals, Linear time...","Biomedical signal Processing: Brain signals-local field potentials (LFP), electrocorticogram, (ECG),...","Heart signals - Electrocardiogram, Heart rate variability, Fetal ECG","Electromyogram"]'::jsonb),
  ('Civil Engineering', 'GET 101', 'Engineer in Society', '100 Level', 'first', 1, false, 'History, evolution and philosophy of science. engineering and technology. The engineering profession - engineering family (engineers, technologists, technicians and craftsmen), professional bodies and societies. Engineers'' code of conduct and ethics, and engineering literacy. Sustainable development goals (SDGs), innovation, infrastructures and nation building - economy, politics, business. Safety and risk analysis in engineering practice. Engineering competency skills - curriculum overview, technical, soft and digital skills. Guest seminars and invited lectures from different engineering professional associations.', '["History, evolution and philosophy of science","engineering and technology","The engineering profession - engineering family (engineers, technologists, technicians and craftsmen),...","Engineers'' code of conduct and ethics, and engineering literacy","Sustainable development goals (SDGs), innovation, infrastructures and nation building - economy, politics,...","Safety and risk analysis in engineering practice","Engineering competency skills - curriculum overview, technical, soft and digital skills","Guest seminars and invited lectures from different engineering professional associations"]'::jsonb),
  ('Civil Engineering', 'GET 102', 'Engineering Graphics and Solid Modelling I', '100 Level', 'second', 2, false, 'Introduction to design thinking and engineering graphics. First and third angle orthogonal projections. Isometric projections; sectioning, conventional practices, conic sections and development. Freehand and guided sketching - pictorial and orthographic. Visualisation and solid modelling in design, prototyping and product-making. User interfaces in concrete terms. Design, drawing, animation, rendering and simulation workspaces. Sketching of 3D objects. Viewports and sectioning to shop drawings in orthographic projections and perspectives. Automated viewports. Sheet metal and surface modelling. Material selection and rendering. This course will use latest professional design tools such as fusion 360, solid works, solid edge or equivalent.', '["Introduction to design thinking and engineering graphics","First and third angle orthogonal projections","Isometric projections","sectioning, conventional practices, conic sections and development","Freehand and guided sketching - pictorial and orthographic","Visualisation and solid modelling in design, prototyping and product-making","User interfaces in concrete terms","Design, drawing, animation, rendering and simulation workspaces"]'::jsonb),
  ('Civil Engineering', 'CEE 101', 'Introduction to Civil Engineering', '100 Level', 'first', 2, false, 'History of civil engineering. Branches of civil engineering. Roles of civil engineers in government, industry and academia. Allied professionals and their interaction with civil engineers. Career oppoturnities in civil engineering, professional and regulatory bodies. 200 Level', '["History of civil engineering","Branches of civil engineering","Roles of civil engineers in government, industry and academia","Allied professionals and their interaction with civil engineers","Career oppoturnities in civil engineering, professional and regulatory bodies","200 Level"]'::jsonb),
  ('Civil Engineering', 'ENT 211', 'Entrepreneurship and Innovation', '200 Level', 'first', 2, false, 'The concept of entrepreneurship (entrepreneurship, intrapreneurship/corporate entrepreneurship); theories, rationale and relevance of entrepreneurship (Schumpeterian and other perspectives, risk-taking, necessity and opportunity-based entrepreneurship, and creative destruction); characteristics of entrepreneurs (opportunity seeker, risk-taker, natural and nurtured, problem solver and change agent, innovator and creative thinker); entrepreneurial thinking (critical thinking, reflective thinking and creative thinking). Innovation (The concept of innovation, dimensions of innovation, change and innovation, knowledge and innovation). Enterprise formation, partnership and networking (basics of business plan, forms of business ownership, business registration and alliance formation, and joint ventures). Contemporary entrepreneurship issues (knowledge, skills and technology, intellectual property, virtual office and networking). Entrepreneurship in Nigeria (biography of inspirational entrepreneurs, youth and women entrepreneurship, entrepreneurship support institutions, youth enterprise networks and environmental and cultural barriers to entrepreneurship). Basic principles of e-commerce.', '["The concept of entrepreneurship (entrepreneurship, intrapreneurship/corporate entrepreneurship)","theories, rationale and relevance of entrepreneurship (Schumpeterian and other perspectives, risk-taking,...","characteristics of entrepreneurs (opportunity seeker, risk-taker, natural and nurtured, problem solver and...","entrepreneurial thinking (critical thinking, reflective thinking and creative thinking)","Innovation (The concept of innovation, dimensions of innovation, change and innovation, knowledge and...","Enterprise formation, partnership and networking (basics of business plan, forms of business ownership,...","Contemporary entrepreneurship issues (knowledge, skills and technology, intellectual property, virtual...","Entrepreneurship in Nigeria (biography of inspirational entrepreneurs, youth and women entrepreneurship,..."]'::jsonb),
  ('Civil Engineering', 'GET 201', 'Applied Electricity I', '200 Level', 'first', 3, false, 'Fundamental concepts: Electric fields, charges, magnetic fields. current, B-H curves Kirchhoff''s laws, superposition. Thevenin, Norton theorems, Reciprocity, RL, RC, RLC circuits. DC, AC bridges, Resistance, Capacitance, Inductance measurement, Transducers, Single phase circuits, Complex j - notation, AC circuits, impedance, admittance, susceptance.', '["Fundamental concepts: Electric fields, charges, magnetic fields","current, B-H curves Kirchhoff''s laws, superposition","Thevenin, Norton theorems, Reciprocity, RL, RC, RLC circuits","DC, AC bridges, Resistance, Capacitance, Inductance measurement, Transducers, Single phase circuits,..."]'::jsonb),
  ('Civil Engineering', 'GET 202', 'Engineering Materials', '200 Level', 'second', 3, false, 'Basic material science; atomic structure, atomic bonding and crystal structures. Engineering materials situating metals and alloys; metals and alloys, classifications of metals, metal extraction processes using iron and steel (ferrous) and aluminium (nonferrous) as examples, phase diagrams/iron carbon diagrams, and mechanical workings of metals. Selection and applications of metals and alloys for specific applications in oil, aerospace, construction, manufacturing and transportation industries, among others. Ceramics (including glass); definition, properties, structure and classifications of ceramics. Bioactive and glass - ceramics. Toughing mechanism for ceramics. Polymers; definition of polymers as engineering materials, chemistry of polymeric materials, polymer crystallisation, polymer degradation and aging. Thermoplastic and thermosetting polymers and concepts of copolymers and homopolymers. Composites; definition, classification, characterisation, properties and composite. Applications of composites. Nanomaterials; definition, classification and applications of nanomaterials as emerging technology. Processing of nanomaterials including mechanical grinding, wet chemical synthesis, gas phase synthesis, sputtered plasma processing, microwave plasma processing and laser ablation. Integrity assessment of engineering materials; effect of engineering design, engineering materials processing, selection, manufacturing and assembling on the performance and service life of engineering materials. Metallography and fractography of materials. Mechanical testing (destructive testing) of materials such as', '["Basic material science","atomic structure, atomic bonding and crystal structures","Engineering materials situating metals and alloys","metals and alloys, classifications of metals, metal extraction processes using iron and steel (ferrous)...","Selection and applications of metals and alloys for specific applications in oil, aerospace, construction,...","Ceramics (including glass)","definition, properties, structure and classifications of ceramics","Bioactive and glass - ceramics"]'::jsonb),
  ('Civil Engineering', 'GET 204', 'Students Workshop Practice', '200 Level', 'second', 2, false, 'The course comprises general, mechanical and electrical components: supervised hands-on experience in safe usage of tools and machines for selected tasks; Use of measuring instruments (calipers, micrometers, gauges, sine bar, wood planners, saws, sanders, and pattern making). Machine shop: lathe work shaping, milling, grinding, reaming, metal spinning. Hand tools, gas and arc welding, cutting, brazing and soldering. Foundry practice.Industrial safety and accident prevention, ergonomics, metrology. Casting processes. Metal forming processes: hot-working and cold-working processes (forging, press- tool work, spinning, etc.). Metal joining processes(welding, brazing and soldering). Heat treatment. Material removal processes. machine tools and classification. Simple theory of metal cutting. Tool action and cutting forces. Introduction to CNC machines. Supervised identification, use and care of various electrical and electronic components such as resistors, inductors, capacitors, diodes and transistors. Exposure to different electric circuits, wiring schemes, analogue and digital electrical and electronic measurements. Household and industrial energy consumption measurements. Practical energy conservation principles.', '["The course comprises general, mechanical and electrical components: supervised hands-on experience in safe...","Use of measuring instruments (calipers, micrometers, gauges, sine bar, wood planners, saws, sanders, and...","Machine shop: lathe work shaping, milling, grinding, reaming, metal spinning","Hand tools, gas and arc welding, cutting, brazing and soldering","Foundry practice.Industrial safety and accident prevention, ergonomics, metrology","Casting processes","Metal forming processes: hot-working and cold-working processes (forging, press- tool work, spinning, etc.)","Metal joining processes(welding, brazing and soldering)"]'::jsonb),
  ('Civil Engineering', 'GET 205', 'Fundamentals of Fluid Mechanics', '200 Level', 'first', 3, false, 'Fluid properties, hydrostatics, fluid dynamics using principles of mass, momentum and energy conservation from a control volume approach. Flow measurements in pipes, dimensional analysis, and similitude, 2-dimensional flows. Hydropower systems.', '["Fluid properties, hydrostatics, fluid dynamics using principles of mass, momentum and energy conservation...","Flow measurements in pipes, dimensional analysis, and similitude, 2-dimensional flows","Hydropower systems"]'::jsonb),
  ('Civil Engineering', 'GET 206', 'Fundamentals of Thermodynamics', '200 Level', 'second', 3, false, 'Basic concepts, definitions and laws (quantitative relations of Zeroth, first, second and third laws of thermodynamics). Properties of pure substances: the two-property rule (P-v-T behaviour of pure substances and perfect gases); state diagrams. The principle of corresponding state; compressibility relations; reduced pressure; reduced volume; temperature; pseudo-critical constants. The ideal gas: specific heat, polytropic processes. Ideal gas cycles; Carnot; thermodynamic cycles, turbines, steam and gas, refrigeration. The first law of thermodynamics - heat and work, applications to open and closed systems. The steady flow energy equation (Bernoulli''s equation) and application. Second law of thermodynamics, heat cycles and efficiencies.', '["Basic concepts, definitions and laws (quantitative relations of Zeroth, first, second and third laws of...","Properties of pure substances: the two-property rule (P-v-T behaviour of pure substances and perfect gases)","state diagrams","The principle of corresponding state","compressibility relations","reduced pressure","reduced volume","temperature"]'::jsonb),
  ('Civil Engineering', 'GET 208', 'Strength of Materials', '200 Level', 'second', 3, false, 'Consideration of equilibrium; composite members, stress-strain relation. Generalised Hooke''s law. Stresses and strains due to loading and temperature changes. Torsion of circular members. Shear force, bending moments and bending stresses in beams with symmetrical and combined loadings. Stress and strain transformation equations and Mohr''s circle. Elastic buckling of columns.', '["Consideration of equilibrium","composite members, stress-strain relation","Generalised Hooke''s law","Stresses and strains due to loading and temperature changes","Torsion of circular members","Shear force, bending moments and bending stresses in beams with symmetrical and combined loadings","Stress and strain transformation equations and Mohr''s circle","Elastic buckling of columns"]'::jsonb),
  ('Civil Engineering', 'GET 209', 'Engineering Mathematics I', '200 Level', 'first', 3, false, 'Limits, continuity, differentiation, introduction to linear first order differential equations, partial and total derivatives, composite functions, matrices and determinants, vector algebra, vector calculus, directional derivatives.', '["Limits, continuity, differentiation, introduction to linear first order differential equations, partial..."]'::jsonb),
  ('Civil Engineering', 'GET 210', 'Engineering Mathematics II', '200 Level', 'second', 3, false, 'Introduction to ordinary differential equations (ODEs); theory, applications, methods of solution; second order differential equations. Advanced topics in calculus (vectors and vector-valued function, line integral, multiple integral and their applications). Elementary complex analysis including functions of complex variables, limits and continuity. Derivatives, differentiation rules and differentiation of integrals. Cauchy-Riemann equation, harmonic functions, basic theory of conformal mapping, transformation and mapping and its applications to engineering problems. Special functions.', '["Introduction to ordinary differential equations (ODEs)","theory, applications, methods of solution","second order differential equations","Advanced topics in calculus (vectors and vector-valued function, line integral, multiple integral and...","Elementary complex analysis including functions of complex variables, limits and continuity","Derivatives, differentiation rules and differentiation of integrals","Cauchy-Riemann equation, harmonic functions, basic theory of conformal mapping, transformation and mapping...","Special functions"]'::jsonb),
  ('Civil Engineering', 'GET 211', 'Computing and Software Engineering', '200 Level', 'first', 3, false, 'Introduction to computers and computing; computer organisation - data processing, memory, registers and addressing schemes; Boolean algebra; floating-point arithmetic; representation of non-numeric information; problem-solving and algorithm development; coding (solution design using flowcharts and pseudo codes). Data models and data structures; computer software and operating system; computer operators and operators precedence; components of computer programs; introduction to object oriented, structured and visual programming; use of MATLAB in engineering applications. ICT fundamentals, Internet of Things (IoT). Elements of software engineering.', '["Introduction to computers and computing","computer organisation - data processing, memory, registers and addressing schemes","Boolean algebra","floating-point arithmetic","representation of non-numeric information","problem-solving and algorithm development","coding (solution design using flowcharts and pseudo codes)","Data models and data structures"]'::jsonb),
  ('Civil Engineering', 'CEE 201', 'Civil Engineering Drawing', '200 Level', 'first', 2, false, 'Drawing and detailing (by hand and using computer-aided-design skills) of civil engineering structures,for example building structures, highways, pipelines, bridges, dams, foundations, etc. utilizing standard symbols and conventions, dimensions, notes, titles, etc. Relationship to specifications. 300 Level', '["Drawing and detailing (by hand and using computer-aided-design skills) of civil engineering structures,for...","utilizing standard symbols and conventions, dimensions, notes, titles, etc","Relationship to specifications","300 Level"]'::jsonb),
  ('Civil Engineering', 'ENT 312', 'Venture Creation', '300 Level', 'second', 2, false, 'Opportunity identification (sources of business opportunities in Nigeria, environmental scanning, demand and supply gap/unmet needs/market gaps/market research, unutilised resources, social and climate conditions and technology adoption gap). business development (business planning, market research). Entrepreneurial finance (venture capital, equity finance, micro-finance, personal savings, small business investment organizations and business plan competition). Entrepreneurial marketing and e-commerce (principles of marketing, customer acquisition & retention, B2B, C2C and B2C models of e-commerce, First Mover Advantage, E-commerce business models and successful e-commerce companies). Small business management/family business: Leadership & Management, basic book keeping, nature of family business and family business growth model. Negotiation and business communication (strategy and tactics of negotiation/bargaining, traditional and modern business communication methods). Opportunity discovery demonstrations (business idea generation presentations, business idea contest, brainstorming sessions, idea pitching). Technological solutions (The concept of market/customer solution, customer solution and emerging technologies, business applications of new technologies - artificial intelligence (AI), virtual/mixed reality (VR), Internet of things (IoTs), blockchain, cloud computing, renewable energy, etc. Digital business and e-commerce strategies).', '["Opportunity identification (sources of business opportunities in Nigeria, environmental scanning, demand...","business development (business planning, market research)","Entrepreneurial finance (venture capital, equity finance, micro-finance, personal savings, small business...","Entrepreneurial marketing and e-commerce (principles of marketing, customer acquisition & retention, B2B,...","Small business management/family business: Leadership & Management, basic book keeping, nature of family...","Negotiation and business communication (strategy and tactics of negotiation/bargaining, traditional and...","Opportunity discovery demonstrations (business idea generation presentations, business idea contest,...","Technological solutions (The concept of market/customer solution, customer solution and emerging..."]'::jsonb),
  ('Civil Engineering', 'GET 301', 'Engineering Mathematics III', '300 Level', 'first', 3, false, 'Linear Algebra. Elements of Matrices, Determinants, Inverses of Matrices. Theory of Linear Equations. Eigen Values and Eigen Vectors. Analytical Geometry. Coordinate Transformation. Solid Geometry. Polar, cylindrical and spherical coordinates. Elements of functions of several variables. Surface Variables. Ordinary Integrals. Evaluation of Double Integrals, Triple', '["Linear Algebra","Elements of Matrices, Determinants, Inverses of Matrices","Theory of Linear Equations","Eigen Values and Eigen Vectors","Analytical Geometry","Coordinate Transformation","Solid Geometry","Polar, cylindrical and spherical coordinates"]'::jsonb),
  ('Civil Engineering', 'GET 302', 'Engineering Mathematics IV', '300 Level', 'second', 3, false, 'Series solution of second order linear differential equations with variable coefficients. Bessel and Legendre equations. Equations with variable coefficients. Sturm-Liouville boundary value problems. Solutions of equations in two and three dimensions by separation of variables. Eigen value problems. Use of operations in the solution of partial differential equations and Linear integral equations. Integral transforms and their inverse including Fourier, Laplace, Mellin and Handel Transforms. Convolution integrals and Hilbert Transforms. Calculus of finite differences. Interpolation formulae. Finite difference equations. RungeKutta and other methods in the solutions of ODE and PDEs. Numerical integration and differentiation.', '["Series solution of second order linear differential equations with variable coefficients","Bessel and Legendre equations","Equations with variable coefficients","Sturm-Liouville boundary value problems","Solutions of equations in two and three dimensions by separation of variables","Eigen value problems","Use of operations in the solution of partial differential equations and Linear integral equations","Integral transforms and their inverse including Fourier, Laplace, Mellin and Handel Transforms"]'::jsonb),
  ('Civil Engineering', 'GET 304', 'Engineering Communication, Technical Writing and Presentation', '300 Level', 'second', 3, false, 'A brief review of common pitfalls in writing. Principles of clear writing (punctuations and capitalization). Figures of speech. Units of grammar. Tenses and verb agreement. Active and passive sentences Lexis and structure Fog Index concept. Skills for communication and communication algorithm. Types and goals of communication; Interpersonal communication; features and the Finger Model or A,B,C,D,E of good interpersonal communication (accuracy of technical terms, brevity of expression, clarity of purpose, directness of focus and effectiveness of the report). Language and organisation of reports. Technical report writing skills(steps, problems in writing, distinguishing technical and other reports, significance, format and styles of writing technical reports). Different formats for communication; styles of correspondences - business report and proposal, business letter, memorandum, e-mails, etc.', '["A brief review of common pitfalls in writing","Principles of clear writing (punctuations and capitalization)","Figures of speech","Units of grammar","Tenses and verb agreement","Active and passive sentences Lexis and structure Fog Index concept","Skills for communication and communication algorithm","Types and goals of communication"]'::jsonb),
  ('Civil Engineering', 'GET 305', 'Engineering Statistics and Data Analytics', '300 Level', 'first', 3, false, 'Descriptive statistics, frequency distribution, populations and sample, central tendency, variance data sampling, mean, median, mode, mean deviation and percentiles. Probability. Binomial, Poisson hyper-geometric and normal distributions. Statistical inference intervals, test hypothesis and significance. Regression and correlation. Introduction to big data analytics and cloud computing applications. Introduction to the R language; R as a calculator; Vectors, matrices, factors, data frames and other R collections. Iteration and looping control structures. Conditionals and other controls. Designing, using and extending functions. The Apply Family. Statistical modelling and inference in R.', '["Descriptive statistics, frequency distribution, populations and sample, central tendency, variance data...","Probability","Binomial, Poisson hyper-geometric and normal distributions","Statistical inference intervals, test hypothesis and significance","Regression and correlation","Introduction to big data analytics and cloud computing applications","Introduction to the R language","R as a calculator"]'::jsonb),
  ('Civil Engineering', 'GET 306', 'Renewable Energy Systems and Technology', '300 Level', 'second', 3, false, 'Current and potential future energy systems in Nigeria and globally - resources, extraction, concepts in energy conversion systems; parallels and differences in various conversion systems and end-use technologies, with emphasis on meeting 21st-century national, regional and global energy needs in a sustainable manner. Various energy technologies in each fuel cycle stage for fossil (oil, gas, synthetic), nuclear (fission and fusion) and renewable (solar, biomass, wind, hydro, and geothermal). Energy types, storage, transmission and conservation. Analysis of energy mixes within an engineering, economic and social context. Sustainable energy; emphasise sustainability in general and in the overall concept of sustainable development and the link this has with sustainable energy as the fundamental benefit of renewable energy. Practical Contents Simple measurement of solar radiation, bomb calorimeter determination of calorific value of fuels and biomass; measurement of the velocity of wind, waves and the energy that abound in them; laboratory production of biogas and determination of energy available in it; simple conversion of solar energy to electricity; transesterification of edible oil into biodiesel; simulation of geothermal energy; Geiger-Muller or Scintillation Counters'' determination of uranium or thorium energy; simple solid or salt storage of energy; hybrid application of renewable energy.', '["Current and potential future energy systems in Nigeria and globally - resources, extraction, concepts in...","parallels and differences in various conversion systems and end-use technologies, with emphasis on meeting...","Various energy technologies in each fuel cycle stage for fossil (oil, gas, synthetic), nuclear (fission...","Energy types, storage, transmission and conservation","Analysis of energy mixes within an engineering, economic and social context","Sustainable energy","emphasise sustainability in general and in the overall concept of sustainable development and the link...","Practical Contents Simple measurement of solar radiation, bomb calorimeter determination of calorific..."]'::jsonb),
  ('Civil Engineering', 'GET 307', 'Introduction to Artificial Intelligence, Machine Learning and Convergent Technologies', '300 Level', 'first', 3, false, '', '[]'::jsonb),
  ('Civil Engineering', 'CEE 301', 'Fluid Mechanics', '300 Level', 'first', 3, false, 'Introduction to incompressible viscous flow, laminar and turbulent flows, Reynolds number; boundary layer flow, lift and drag. Laminar flow - in pipes, between parallel plates. Turbulent flows - along a plate, in ducts and pipes. Physical hydraulic models. Interconnected pipes and pipe network analysis. Potential flows and application to flow nets. steady and unsteady flow in closed conduits; water hammer, surge tanks.', '["Introduction to incompressible viscous flow, laminar and turbulent flows, Reynolds number","boundary layer flow, lift and drag","Laminar flow - in pipes, between parallel plates","Turbulent flows - along a plate, in ducts and pipes","Physical hydraulic models","Interconnected pipes and pipe network analysis","Potential flows and application to flow nets","steady and unsteady flow in closed conduits"]'::jsonb),
  ('Civil Engineering', 'CEE 303', 'Engineering Geology', '300 Level', 'first', 2, true, 'Geology structures and mapping; rocks and minerals; stratigraphy - time scale - fossils and their importance with special reference to Nigeria. Introduction to the geology of Nigeria; engineering applications - water supply, site investigations for dams, dykes and so on.', '["Geology structures and mapping","rocks and minerals","stratigraphy - time scale - fossils and their importance with special reference to Nigeria","Introduction to the geology of Nigeria","engineering applications - water supply, site investigations for dams, dykes and so on"]'::jsonb),
  ('Civil Engineering', 'CEE 304', 'Civil Engineering materials', '300 Level', 'second', 3, true, 'Concrete Technology - types of cements, aggregates and their properties; concrete mix design, properties and their determination. Steel technology - production, fabrication and', '["Concrete Technology - types of cements, aggregates and their properties","concrete mix design, properties and their determination","Steel technology - production, fabrication and"]'::jsonb),
  ('Civil Engineering', 'CEE 308', 'Engineering Surveying and Photogrammetry I', '300 Level', 'second', 2, false, 'Chain surveying. Compass surveying methods. Contours and their uses. Traversing - methods and applications. Levelling - geodetic levelling - errors and their adjustments; applications. Tachometry- methods, substance heighting, self-adjusting and electromagnetic methods. Introduction to photogrammetry. 400 Level GET 402 Engineering Project I (2 Units C: PH 90) Learning Outcomes At the end of this course, the students should be able to: 1. complete the design phase of a complex engineering problem sourced from industry or community during the SIWES III programme; and 2. demonstrate the connection between engineering product-making and the theoretical courses they have learned following the applicable industry best practices. Course Contents In the second semester of the 400-level students, preferably in groups, work from the university on the identified industry or organization to tackle industry complex engineering problems. Theoretical issues may be provided by the department faculty or industry experts. During the vacation, students will now work full time with the organisation/industry on the project as part of the SIWES III. The students can also go beyond the department and engage in multidisciplinary undertakings. Literature survey, review of existing systems etc. must be achieved to a satisfactory extent. GET 404 Engineering Valuation and Appraisal (2 Units C: LH 30) Learning Outcomes At the end of this course, the students should be able to: 1. identify at least three (3) objectives of engineering valuation work, valuer''s primary duty and responsibility and valuation terminologies; 2. describe at least four (4) Valuer''s obligation to his or her client, to other valuers, and to the society; 3. demonstrate with example the engineering valuation methods, valuation standards, and practices; 4. prepare engineering valuation and appraisal reports and review; 5. discuss expert witnessing and ethics in valuation; and 6. determine price, cost, value, depreciation and obsolescence in real property, personal property, personal property, machinery and equipment, oil, gas, mines, and quarries valuation.', '["Chain surveying","Compass surveying methods","Contours and their uses","Traversing - methods and applications","Levelling - geodetic levelling - errors and their adjustments","applications","Tachometry- methods, substance heighting, self-adjusting and electromagnetic methods","Introduction to photogrammetry"]'::jsonb),
  ('Civil Engineering', 'GET 402', 'Engineering Project I', '400 Level', 'second', 2, false, '', '[]'::jsonb),
  ('Civil Engineering', 'GET 404', 'Engineering Valuation and Costing', '400 Level', 'second', 2, false, '', '[]'::jsonb),
  ('Civil Engineering', 'CEE 406', 'Engineering Surveying and Photo- grammetry II', '400 Level', 'second', 3, false, '', '[]'::jsonb),
  ('Civil Engineering', 'GET 501', 'Engineering Project Management', '500 Level', 'first', 3, false, 'Project management fundamentals - definitions, project environment, nature and characteristics, development practice, management by objectives, and the centrality of engineering to projects, infrastructures, national and global development. The scope of project management - organisational, financial, planning and control, personnel management, labour and public relations, wages and salary administration and resource management. Identification of project stakeholders; beneficiaries and impacted persons - functions, roles, responsibilities. Project community relations, communication and change management. Project planning, control and timeliness;decision making, forecasting, scheduling, work breakdown structure (WBS), deliverables and timelines, logical frameworks (log frames), risk analysis, role of subject matter experts (SMEs), role conflicts; Gantt Chart, CPM and PERT. Optimisation, linear programming as an aid to decision making, transport and materials handling. Monitoring and Evaluation - key performance indices (KPIs); methods of economic and technical evaluation. Industrial psychology, ergonomics/human factors and environmental impact considerations in engineering project design and management. Project business case - financial, technical and sustainability considerations. Case studies, site visits and invited industry professional seminars. General principles of management and appraisal techniques. Breakthrough and control management theory; production and maintenance management. Training and manpower development. The manager and policy formulation, objective setting, planning, organising and controlling, motivation and appraisal of results.', '["Project management fundamentals - definitions, project environment, nature and characteristics,...","The scope of project management - organisational, financial, planning and control, personnel management,...","Identification of project stakeholders","beneficiaries and impacted persons - functions, roles, responsibilities","Project community relations, communication and change management","Project planning, control and timeliness;decision making, forecasting, scheduling, work breakdown...","Gantt Chart, CPM and PERT","Optimisation, linear programming as an aid to decision making, transport and materials handling"]'::jsonb),
  ('Civil Engineering', 'GET 502', 'Engineering Law', '500 Level', 'second', 2, false, 'Common Law: its history, definition, nature and division. Legislation, codification interpretation. Equity: definition and its main spheres. Law of contracts for Engineers: Forms of contract and criteria for selecting contractors; offer, acceptance, communication termination of contract. Terms of Contracts; suppliers'' duties - Damages and other Remedies.', '["Common Law: its history, definition, nature and division","Legislation, codification interpretation","Equity: definition and its main spheres","Law of contracts for Engineers: Forms of contract and criteria for selecting contractors","offer, acceptance, communication termination of contract","Terms of Contracts","suppliers'' duties - Damages and other Remedies"]'::jsonb),
  ('Civil Engineering', 'CEE 506', 'Construction Engineering', '500 Level', 'second', 3, false, 'Construction practices and professional relations. Earth-works. Construction equipment and techniques. Form-work design, component assembly. Improvement of productivity and construction practices. Safety. Capital outlay and operating cost, project financing, insurance and bonding, contract terms. Solutions to job site and engineering problems in buildings and heavy construction in Nigeria.', '["Construction practices and professional relations","Earth-works","Construction equipment and techniques","Form-work design, component assembly","Improvement of productivity and construction practices","Capital outlay and operating cost, project financing, insurance and bonding, contract terms","Solutions to job site and engineering problems in buildings and heavy construction in Nigeria"]'::jsonb),
  ('Civil Engineering', 'CEE 599', 'Project', '500 Level', 'first', 6, false, 'For proper guidance of the students, projects will depend on the available academic staff expertise and interest but the projects should be preferably of investigatory nature. Preferably, students should be advised to choose projects in the same area as their option subjects. Minimum Academic Standards Equipment List of Laboratories/Workshop and Equipment Structural Engineering 1. Civil Engineering Materials Laboratory 2. Structures Laboratory: Routine testing Models and prototype testing Studio/design office', '["For proper guidance of the students, projects will depend on the available academic staff expertise and...","Preferably, students should be advised to choose projects in the same area as their option subjects","Minimum Academic Standards Equipment List of Laboratories/Workshop and Equipment Structural Engineering 1","Civil Engineering Materials Laboratory 2","Structures Laboratory: Routine testing Models and prototype testing Studio/design office"]'::jsonb),
  ('Electronic Engineering', 'GET 101', 'Engineer in Society', '100 Level', 'first', 1, false, 'History, evolution and philosophy of science. engineering and technology. The engineering profession - engineering family (engineers, technologists, technicians and craftsmen), professional bodies and societies. Engineers'' code of conduct and ethics, and engineering literacy. Sustainable development goals (SDGs), innovation, infrastructures and nation building - economy, politics, business. Safety and risk analysis in engineering practice. Engineering competency skills - curriculum overview, technical, soft and digital skills. Guest seminars and invited lectures from different engineering professional associations.', '["History, evolution and philosophy of science","engineering and technology","The engineering profession - engineering family (engineers, technologists, technicians and craftsmen),...","Engineers'' code of conduct and ethics, and engineering literacy","Sustainable development goals (SDGs), innovation, infrastructures and nation building - economy, politics,...","Safety and risk analysis in engineering practice","Engineering competency skills - curriculum overview, technical, soft and digital skills","Guest seminars and invited lectures from different engineering professional associations"]'::jsonb),
  ('Electronic Engineering', 'GET 102', 'Engineering Graphics and Solid Modelling I', '100 Level', 'second', 2, false, 'Introduction to design thinking and engineering graphics. First and third angle orthogonal projections. Isometric projections; sectioning, conventional practices, conic sections and development. Freehand and guided sketching - pictorial and orthographic. Visualisation and solid modelling in design, prototyping and product-making. User interfaces in concrete', '["Introduction to design thinking and engineering graphics","First and third angle orthogonal projections","Isometric projections","sectioning, conventional practices, conic sections and development","Freehand and guided sketching - pictorial and orthographic","Visualisation and solid modelling in design, prototyping and product-making","User interfaces in concrete"]'::jsonb),
  ('Electronic Engineering', 'CPE 102', 'Introduction to Computer Engineering', '100 Level', 'second', 2, false, '', '[]'::jsonb),
  ('Electronic Engineering', 'GET 201', 'Applied Electricity I', '200 Level', 'first', 3, false, 'Fundamental concepts: Electric fields, charges, magnetic fields. current, B-H curves Kirchhoff''s laws, superposition. Thevenin, Norton theorems, Reciprocity, RL, RC, RLC circuits. DC, AC bridges, Resistance, Capacitance, Inductance measurement, Transducers, Single phase circuits, Complex j - notation, AC circuits, impedance, admittance, acceptance.', '["Fundamental concepts: Electric fields, charges, magnetic fields","current, B-H curves Kirchhoff''s laws, superposition","Thevenin, Norton theorems, Reciprocity, RL, RC, RLC circuits","DC, AC bridges, Resistance, Capacitance, Inductance measurement, Transducers, Single phase circuits,..."]'::jsonb),
  ('Electronic Engineering', 'GET 202', 'Engineering Materials', '200 Level', 'second', 3, false, 'The material science; atomic structure, atomic bonding and crystal structures. Engineering materials situating metals and alloys; metals and alloys, classifications of metals, metal extraction processes using iron and steel (ferrous) and aluminium (nonferrous) as examples, phase diagrams/iron carbon diagrams, and mechanical workings of metals. Selection and applications of metals and alloys for specific applications in oil, aerospace, construction, manufacturing and transportation industries, among others. Ceramics (including glass); definition, properties, structure and classifications of ceramics. Bioactive and glass - ceramics. Toughing mechanism for ceramics. Polymers: definition of polymers as engineering materials; chemistry of polymeric materials, polymer crystallisation, polymer degradation and aging.', '["The material science","atomic structure, atomic bonding and crystal structures","Engineering materials situating metals and alloys","metals and alloys, classifications of metals, metal extraction processes using iron and steel (ferrous)...","Selection and applications of metals and alloys for specific applications in oil, aerospace, construction,...","Ceramics (including glass)","definition, properties, structure and classifications of ceramics","Bioactive and glass - ceramics"]'::jsonb),
  ('Electronic Engineering', 'GET 203', 'Engineering Graphics and Solid Modeling II', '200 Level', 'first', 2, false, 'Projection of lines, auxiliary views and mixed projection. Preparation of detailed working production drawing; semi-detailed drawings, conventional presentation methods. Solid, surface and shell modeling. Faces, bodies and surface intersections. Component-based design. Component assembly and motion constraints. Constrained motions and animation. Introduction to electronics modeling. Electronics board layout preparation, Component libraries and Schematic design. Parametric modeling and adaptive design. Simulation for material optimization. Designing for manufacturing. Additive and subtractive manufacturing. Production for 3-D printing, Laser cutting and CNC machinery.Arrangement of engineering components to form a working plant (Assembly Drawing of a Plant).', '["Projection of lines, auxiliary views and mixed projection","Preparation of detailed working production drawing","semi-detailed drawings, conventional presentation methods","Solid, surface and shell modeling","Faces, bodies and surface intersections","Component-based design","Component assembly and motion constraints","Constrained motions and animation"]'::jsonb),
  ('Electronic Engineering', 'GET 204', 'Students Workshop Practice', '200 Level', 'second', 2, false, 'The course comprises general, mechanical and electrical components: supervised hands-on experience in safe usage of tools and machines for selected tasks; Use of measuring instruments (calipers, micrometers, gauges, sine bar, wood planners, saws, sanders, and pattern making). Machine shop: lathe work shaping, milling, grinding, reaming, metal spinning. Hand tools, gas and arc welding, cutting, brazing and soldering. Foundry practice.Industrial safety and accident prevention, ergonomics, metrology. Casting processes. Metal forming processes: hot-working and cold-working processes (forging, press- tool work, spinning, etc.). Metal joining processes(welding, brazing and soldering). Heat treatment. Material removal processes. machine tools and classification. Simple theory of metal cutting. Tool action and cutting forces. Introduction to CNC machines. Supervised identification, use and care of various electrical and electronic components such as resistors, inductors, capacitors, diodes and transistors. Exposure to different electric circuits, wiring schemes, analogue and digital electrical and electronic measurements. Household and industrial energy consumption measurements. Practical energy conservation principles.', '["The course comprises general, mechanical and electrical components: supervised hands-on experience in safe...","Use of measuring instruments (calipers, micrometers, gauges, sine bar, wood planners, saws, sanders, and...","Machine shop: lathe work shaping, milling, grinding, reaming, metal spinning","Hand tools, gas and arc welding, cutting, brazing and soldering","Foundry practice.Industrial safety and accident prevention, ergonomics, metrology","Casting processes","Metal forming processes: hot-working and cold-working processes (forging, press- tool work, spinning, etc.)","Metal joining processes(welding, brazing and soldering)"]'::jsonb),
  ('Electronic Engineering', 'GET 207', 'Applied Mechanics', '200 Level', 'first', 3, false, 'Forces, moments, couples. Equilibrium of simple structures and machine parts. Friction. First and second moments of area; centroids. Kinematics of particles and rigid bodies in plane motion. Newton''s laws of motion. Kinetic energy and momentum analyse.', '["Forces, moments, couples","Equilibrium of simple structures and machine parts","First and second moments of area","centroids","Kinematics of particles and rigid bodies in plane motion","Newton''s laws of motion","Kinetic energy and momentum analyse"]'::jsonb),
  ('Electronic Engineering', 'GET 209', 'Engineering Mathematics I', '200 Level', 'first', 3, false, 'Limits, continuity, differentiation, introduction to linear first order differential equations, partial and total derivatives, composite functions, matrices and determinants, vector algebra, vector calculus, directional derivatives.', '["Limits, continuity, differentiation, introduction to linear first order differential equations, partial..."]'::jsonb),
  ('Electronic Engineering', 'GET 211', 'Computing and Software Engineering', '200 Level', 'first', 3, false, 'Introduction to computers and computing; computer organisation - data processing, memory, registers and addressing schemes; Boolean algebra; floating-point arithmetic; representation of non-numeric information; problem-solving and algorithm development; coding (solution design using flowcharts and pseudo codes). Data models and data structures; computer software and operating system; computer operators and operators precedence; components of computer programs; introduction to object oriented, structured and visual programming; use of MATLAB in engineering applications. ICT fundamentals, Internet of Things (IoT). Elements of software engineering.', '["Introduction to computers and computing","computer organisation - data processing, memory, registers and addressing schemes","Boolean algebra","floating-point arithmetic","representation of non-numeric information","problem-solving and algorithm development","coding (solution design using flowcharts and pseudo codes)","Data models and data structures"]'::jsonb),
  ('Electronic Engineering', 'GET 210', 'Engineering Mathematics II', '200 Level', 'second', 3, false, 'Introduction to ordinary differential equations (ODEs); theory, applications, methods of solution; second order differential equations. Advanced topics in calculus (vectors and vector-valued function, line integral, multiple integral and their applications). Elementary complex analysis including functions of complex variables, limits and continuity. Derivatives, differentiation rules and differentiation of integrals. Cauchy-Riemann equation, harmonic functions, basic theory of conformal mapping, transformation and mapping and its applications to engineering problems. Special functions.', '["Introduction to ordinary differential equations (ODEs)","theory, applications, methods of solution","second order differential equations","Advanced topics in calculus (vectors and vector-valued function, line integral, multiple integral and...","Elementary complex analysis including functions of complex variables, limits and continuity","Derivatives, differentiation rules and differentiation of integrals","Cauchy-Riemann equation, harmonic functions, basic theory of conformal mapping, transformation and mapping...","Special functions"]'::jsonb),
  ('Electronic Engineering', 'ENT 312', 'Venture Creation', '300 Level', 'second', 2, false, 'Opportunity identification (sources of business opportunities in Nigeria, environmental scanning, demand and supply gap/unmet needs/market gaps/market research, unutilised resources, social and climate conditions and technology adoption gap). business development (business planning, market research). Entrepreneurial finance (venture capital, equity finance, micro-finance, personal savings, small business investment organizations and business plan competition). Entrepreneurial marketing and e-commerce (principles of marketing, customer acquisition & retention, B2B, C2C and B2C models of e-commerce, First Mover Advantage, E-commerce business models and successful e-commerce companies). Small business management/family business: Leadership & Management, basic book keeping, nature of family business and family business growth model. Negotiation and business communication (strategy and tactics of negotiation/bargaining, traditional and modern business communication methods). Opportunity discovery demonstrations (business idea generation presentations, business idea contest, brainstorming sessions, idea pitching). Technological solutions (The concept of market/customer solution, customer solution and emerging technologies, business applications of new technologies - artificial intelligence (AI), virtual/mixed reality (VR), Internet of things (IoTs), blockchain, cloud computing, renewable energy, etc. Digital business and e-commerce strategies).', '["Opportunity identification (sources of business opportunities in Nigeria, environmental scanning, demand...","business development (business planning, market research)","Entrepreneurial finance (venture capital, equity finance, micro-finance, personal savings, small business...","Entrepreneurial marketing and e-commerce (principles of marketing, customer acquisition & retention, B2B,...","Small business management/family business: Leadership & Management, basic book keeping, nature of family...","Negotiation and business communication (strategy and tactics of negotiation/bargaining, traditional and...","Opportunity discovery demonstrations (business idea generation presentations, business idea contest,...","Technological solutions (The concept of market/customer solution, customer solution and emerging..."]'::jsonb),
  ('Electronic Engineering', 'GET 301', 'Engineering Mathematics III', '300 Level', 'first', 3, false, '', '[]'::jsonb),
  ('Electronic Engineering', 'GET 302', 'Engineering Mathematics IV', '300 Level', 'second', 3, false, 'Series solution of second order linear differential equations with variable coefficients. Bessel and Legendre equations. Equations with variable coefficients. Sturm-Liouville boundary value problems. Solutions of equations in two and three dimensions by separation of variables. Eigen value problems. Use of operations in the solution of partial differential equations and Linear integral equations. Integral transforms and their inverse including Fourier, Laplace, Mellin and Handel Transforms. Convolution integrals and Hilbert Transforms. Calculus of finite differences. Interpolation formulae. Finite difference equations. RungeKutta and other methods in the solutions of ODE and PDEs. Numerical integration and differentiation.', '["Series solution of second order linear differential equations with variable coefficients","Bessel and Legendre equations","Equations with variable coefficients","Sturm-Liouville boundary value problems","Solutions of equations in two and three dimensions by separation of variables","Eigen value problems","Use of operations in the solution of partial differential equations and Linear integral equations","Integral transforms and their inverse including Fourier, Laplace, Mellin and Handel Transforms"]'::jsonb),
  ('Electronic Engineering', 'GET 304', 'Engineering Communication, Technical Writing and Presentation', '300 Level', 'second', 3, false, 'A brief review of common pitfalls in writing. Principles of clear writing (punctuations and capitalization). Figures of speech. Units of grammar. Tenses and verb agreement. Active and passive sentences Lexis, structure Fog and Index concept. Skills for communication and communication algorithm. Types and goals of communication; Interpersonal communication; features and the Finger Model or A,B,C,D,E of good interpersonal communication (accuracy of technical terms, brevity of expression, clarity of purpose, directness of focus and effectiveness of the report). Language and organisation of reports. Technical report writing skills (steps, problems in writing, distinguishing technical and other reports, significance, format and styles of writing technical reports). Different formats for communication; styles of correspondences - business report and proposal, business letter, memorandum, e-mails, etc. Proposals for projects and research; format, major steps and tips of grant-oriented proposals. Research reports(competency, major steps, components and formats of research reports and publishable communication). Sources and handling of data, tables, figures, equations and references in a report. Presentation skills; overview, tips, organisation, use of visual aids and practising of presentation. Intellectual property rights in research reports. Case studies of major engineering designs, proposals and industrial failures with professional presentation of reports.', '["A brief review of common pitfalls in writing","Principles of clear writing (punctuations and capitalization)","Figures of speech","Units of grammar","Tenses and verb agreement","Active and passive sentences Lexis, structure Fog and Index concept","Skills for communication and communication algorithm","Types and goals of communication"]'::jsonb),
  ('Electronic Engineering', 'GET 305', 'Engineering Statistics and Data Analytics', '300 Level', 'first', 3, false, 'Descriptive statistics, frequency distribution, populations and sample, central tendency, variance data sampling, mean, median, mode, mean deviation and percentiles. Probability. Binomial, Poisson hyper-geometric, normal distributions. Statistical inference intervals, test hypothesis and significance. Regression and correlation. Introduction to big data analytics and cloud computing applications. Introduction to the R language; R as a calculator; Vectors, matrices, factors, data frames and other R collections. Iteration and looping control structures. Conditionals and other controls. Designing, using and extending functions. The Apply Family. Statistical modelling and inference in R. .', '["Descriptive statistics, frequency distribution, populations and sample, central tendency, variance data...","Probability","Binomial, Poisson hyper-geometric, normal distributions","Statistical inference intervals, test hypothesis and significance","Regression and correlation","Introduction to big data analytics and cloud computing applications","Introduction to the R language","R as a calculator"]'::jsonb),
  ('Electronic Engineering', 'GET 306', 'Renewable Energy Systems and Technologies', '300 Level', 'second', 3, false, 'Current and potential future energy systems in Nigeria and globally - resources, extraction, concepts in energy conversion systems; parallels and differences in various conversion systems and end-use technologies, with emphasis on meeting 21st-century national, regional and global energy needs in a sustainable manner. Various energy technologies in each fuel cycle stage for fossil (oil, gas, synthetic), nuclear (fission and fusion) and renewable (solar, biomass, wind, hydro, and geothermal). Energy types, storage, transmission and conservation. Analysis of energy mixes within an engineering, economic and social context. Sustainable energy; emphasise sustainability in general and in the overall concept of sustainable development and the link this has with sustainable energy as the fundamental benefit of renewable energy Practical Contents', '["Current and potential future energy systems in Nigeria and globally - resources, extraction, concepts in...","parallels and differences in various conversion systems and end-use technologies, with emphasis on meeting...","Various energy technologies in each fuel cycle stage for fossil (oil, gas, synthetic), nuclear (fission...","Energy types, storage, transmission and conservation","Analysis of energy mixes within an engineering, economic and social context","Sustainable energy","emphasise sustainability in general and in the overall concept of sustainable development and the link..."]'::jsonb),
  ('Electronic Engineering', 'CPE 301', 'Computer Organisation and Architecture', '300 Level', 'first', 2, false, 'Computer fundamentals: development history of computer hardware and software; hard- wired vs stored program concept; Von-Neuman architecture; Harvard architecture: principle of operation, advantages and disadvantages; single address machine; contemporary computers; computer system: block diagram, functions, examples, dataflow and control line; computer arithmetic: integer arithmetic (addition, subtraction, multiplication, division), floating-point representation (IEEE), floating-point arithmetic, arithmetic and logic unit (ALU). Introduction to CISC and RISC architecture: principle of operation, merits and demerits; storage and input/output systems: computer function (fetch and execute cycles), interrupts, interconnection structures (bus structure and bus types); overview of memory system, memory chip organisation and error correction, cache memory, and memory storage devices; overview of I/O, programmed and interrupt-driven I/Os, DMA, I/O channel and I/O processor; control unit: micro-operations, control of the CPU, hard-wired implementation, control unit operation, micro-instruction sequencing and execution, and micro-programmed control; using INTEL family, and MOTOROLA family as case study of a CISC computer system; instruction set and register: machine instruction characteristics, types of operands and operations, instruction functions, addressing modes, instruction formats, register organisation, and instruction pipelining; high performance computer systems: techniques to achieve high performance, pipelining, storage hierarchy, and units with function dedicated for I/O; RISC, introduction to superscalar processor, and parallel processor; using popular RISC processor (e.g. i960, Motorola PowerPC) as case study. Operating system: overview of operating system, dimension and type of operating system: overview of operating system, dimension and type of operating system, high level scheduling, short-term scheduling, I/O scheduling, memory management, virtual memory, UNIX/LINUX operating system: architecture, commands, programming; window-based operating systems (MS windows).', '["Computer fundamentals: development history of computer hardware and software","hard- wired vs stored program concept","Von-Neuman architecture","Harvard architecture: principle of operation, advantages and disadvantages","single address machine","contemporary computers","computer system: block diagram, functions, examples, dataflow and control line","computer arithmetic: integer arithmetic (addition, subtraction, multiplication, division), floating-point..."]'::jsonb),
  ('Electronic Engineering', 'CPE 302', 'Measurement and Instrumentation', '300 Level', 'second', 3, false, 'Transducers and applications; general instrumentation, basic meters in DC measurement, basic meters in AC measurements, rectifier, voltmeter, electro-dynamometer, and wattmeter, instrument transformers, DC and AC bridges and their applications general form of AC bridge, universal impedance bridge, electronic instruments for the measurement of voltage current resistance and other circuit parameters, electronic voltmeters, AC voltmeters using rectifiers, electronic multi meter, digital voltmeters; oscilloscope, vertical deflection system horizontal deflection system, probes, sampling CRO; and electronic function. generators.', '["Transducers and applications","general instrumentation, basic meters in DC measurement, basic meters in AC measurements, rectifier,...","oscilloscope, vertical deflection system horizontal deflection system, probes, sampling CRO","and electronic function","generators"]'::jsonb),
  ('Electronic Engineering', 'EEE 321', 'Analogue Electronic Circuits', '300 Level', 'first', 2, false, 'Single-stage transistor amplifiers using BJT and FET Equivalent circuits and calculation of current gain, voltage gain, power gain, input and output impedance. Operational Amplifiers: Description, parameters and applications. Feedback, broadband and narrowband amplifiers. Power amplifiers. Voltage and current stabilizing circuits. Voltage amplifiers, multi storage amplifiers using BJTs and FETs.', '["Single-stage transistor amplifiers using BJT and FET Equivalent circuits and calculation of current gain,...","Operational Amplifiers: Description, parameters and applications","Feedback, broadband and narrowband amplifiers","Power amplifiers","Voltage and current stabilizing circuits","Voltage amplifiers, multi storage amplifiers using BJTs and FETs"]'::jsonb),
  ('Electronic Engineering', 'EEE 322', 'Digital Electronic Circuits', '300 Level', 'second', 2, false, 'Number Systems and Codes. Logic Gate Simplification of Logic expressions using Boolean algebra. Simplification of Logic expressions using Karnaugh Method. Design of combinational circuit. Flip-Flops. Application of Flip-Flops in the design of counter. Registers and timers. Switching and wave shaping circuits. Generation of non-sinusoidal signal (multivibrators). Introduction to ADC and DAC. Design of Logic Gates (Diode, DTL, TTL, ECL etc). Sequential circuits. Introduction to microprocessors. 400 Level GET 402 Engineering Project I (2 Units C: PH 90) Learning Outcomes At the end of this course, the students should be able to: 1. complete the design phase of a complex engineering problem sourced from industry or community during the SIWES III programme; and 2. demonstrate the connection between engineering product-making and the theoretical courses they have learned following the applicable industry best practices. Course Contents In the second semester of the 400-level students, preferably in groups, work from the university on the identified industry or organization to tackle industry complex engineering problems. Theoretical issues may be provided by the department faculty or industry experts. During the vacation, students will now work full time with the organisation/industry on the project as part of the SIWES III. The students can also go beyond the department and engage in multidisciplinary undertakings. Literature survey, review of existing systems etc. must be achieved to a satisfactory extent. GET 404 Engineering Valuation and Appraisal (2 Units C: LH 30) Learning Outcomes At the end of this course, the students should be able to: 1. identify at least three (3) objectives of engineering valuation work, valuer''s primary duty and responsibility and valuation terminologies; 2. describe at least four (4) Valuer''s obligation to his or her client, to other valuers, and to the society;', '["Number Systems and Codes","Logic Gate Simplification of Logic expressions using Boolean algebra","Simplification of Logic expressions using Karnaugh Method","Design of combinational circuit","Flip-Flops","Application of Flip-Flops in the design of counter","Registers and timers","Switching and wave shaping circuits"]'::jsonb),
  ('Electronic Engineering', 'GET 402', 'Engineering Project I', '400 Level', 'second', 2, true, '', '[]'::jsonb),
  ('Electronic Engineering', 'GET 404', 'Engineering Valuation and Costing', '400 Level', 'second', 2, false, '', '[]'::jsonb),
  ('Electronic Engineering', 'CPE 401', 'Microprocessor and Embedded Systems', '400 Level', 'first', 3, false, 'A basic microprocessor system: the CPU, memory, I/O, and buses subsystems, basic operation of a microprocessor system: fetch and execute cycle, the architecture of some typical 8-bit, 16-bit microprocessors (INTEL, MOTOROLA) and their features; programming model in real mode: registers, memory, addressing modes; organisation of the interrupt system, interrupt vectors, and external interrupts, implementation of single and multiple interrupts in real mode; programming model in protected mode: registers, memory management and address translation, descriptor and page tables, system control instructions, multitasking and memory protection, addressing modes, and interrupt system; memory interfacing and address decoding; I/O interfacing: memory mapped i/o, isolated i/o, bus timing, i/o instructions; peripheral devices interfacing: 8255 PPI/6821 PIA, 8251 USART/6821 UART, DMA, Timer/Counter chips, etc; instruction set; assembly language Programming of INTEL and MOTOROLA microprocessors; and discussion of a typical system e.g. IBM PC, Apple Macintosh.', '["A basic microprocessor system: the CPU, memory, I/O, and buses subsystems, basic operation of a...","programming model in real mode: registers, memory, addressing modes","organisation of the interrupt system, interrupt vectors, and external interrupts, implementation of single...","programming model in protected mode: registers, memory management and address translation, descriptor and...","memory interfacing and address decoding","I/O interfacing: memory mapped i/o, isolated i/o, bus timing, i/o instructions","peripheral devices interfacing: 8255 PPI/6821 PIA, 8251 USART/6821 UART, DMA, Timer/Counter chips, etc","instruction set"]'::jsonb),
  ('Electronic Engineering', 'CPE 403', 'Control System', '400 Level', 'first', 2, false, 'Basic concepts and examples of control systems; Feedback, Time response analysis, concept of stability, Routh-Hurwitz criterion; Root-locus techniques, Frequency-response analysis, Polar and Bode plots, Nyquist stability criteria. Nichol''s chart, compensation techniques; introduction to non-linear systems.', '["Basic concepts and examples of control systems","Feedback, Time response analysis, concept of stability, Routh-Hurwitz criterion","Root-locus techniques, Frequency-response analysis, Polar and Bode plots, Nyquist stability criteria","Nichol''s chart, compensation techniques","introduction to non-linear systems"]'::jsonb),
  ('Electronic Engineering', 'CPE 405', 'Fundamentals of Software Engineering', '400 Level', 'first', 2, false, 'Introduction to software engineering fundamentals; object-oriented programming; number representations; data structure and algorithms, Abstraction, modules and objects; designing for efficiency; object-oriented software design and implementation.', '["Introduction to software engineering fundamentals","object-oriented programming","number representations","data structure and algorithms, Abstraction, modules and objects","designing for efficiency","object-oriented software design and implementation"]'::jsonb),
  ('Electronic Engineering', 'CPE 411', 'Hardware Design Techniques and Verification', '400 Level', 'first', 2, true, 'Elements of digital computer design; control unit, micro-programming, bus organisation and addressing schemes; micro-processors, system architecture, bus control, instruction execution and addressing modes; machine codes, assembly language and high-level language programming, micro-processors as state machines; microprocessor interfacing: input/output; technique, interrupt systems and direct memory access; interfacing to analogue systems and applications to D/A and A/D converters; system development tools:', '["Elements of digital computer design","control unit, micro-programming, bus organisation and addressing schemes","micro-processors, system architecture, bus control, instruction execution and addressing modes","machine codes, assembly language and high-level language programming, micro-processors as state machines","microprocessor interfacing: input/output","technique, interrupt systems and direct memory access","interfacing to analogue systems and applications to D/A and A/D converters","system development tools:"]'::jsonb),
  ('Electronic Engineering', 'CPE 413', 'Research Methods', '400 Level', 'first', 2, true, 'Origins and definitions of research; problem identification and formulation; research types/design; qualitative, quantitative and mixed methods of research; measurement; sampling; data analysis; interpretation of data and technical report writing; use of encyclopedia, research guides, handbooks, academic databases for computing and computer engineering discipline; use of tools/techniques for research production: referencing formats/styles and software; research management and reporting best practices; plagiarism- definitions, types, detection software; basics of document analysis, systematic review and management methods; practical documentation/presentation projects/seminars.', '["Origins and definitions of research","problem identification and formulation","research types/design","qualitative, quantitative and mixed methods of research","measurement","data analysis","interpretation of data and technical report writing","use of encyclopedia, research guides, handbooks, academic databases for computing and computer engineering..."]'::jsonb),
  ('Electronic Engineering', 'GET 501', 'Engineering Project Management', '500 Level', 'first', 3, false, 'Project management fundamentals - definitions, project environment, nature and characteristics, development practice, management by objectives, and the centrality of engineering to projects, infrastructures, national and global development. The scope of project management - organisational, financial, planning and control, personnel management, labour and public relations, wages and salary administration and resource management. Identification of project stakeholders; beneficiaries and impacted persons - functions, roles, responsibilities. Project community relations, communication and change management. Project planning, control and timeliness;decision making, forecasting, scheduling, work breakdown structure (WBS), deliverables and timelines, logical frameworks (log frames), risk analysis, role of subject matter experts (SMEs), role conflicts; Gantt Chart, CPM and PERT. Optimisation, linear programming as an aid to decision making, transport and materials handling. Monitoring and Evaluation - key performance indices (KPIs); methods of economic and technical evaluation. Industrial psychology, ergonomics/human factors and environmental impact considerations in engineering project design and management. Project business case - financial, technical and sustainability considerations. Case studies, site visits and invited industry professional seminars. General principles of management and appraisal techniques. Breakthrough and control management theory; production and maintenance management. Training and manpower development. The manager and policy formulation, objective setting, planning, organising and controlling, motivation and appraisal of results.', '["Project management fundamentals - definitions, project environment, nature and characteristics,...","The scope of project management - organisational, financial, planning and control, personnel management,...","Identification of project stakeholders","beneficiaries and impacted persons - functions, roles, responsibilities","Project community relations, communication and change management","Project planning, control and timeliness;decision making, forecasting, scheduling, work breakdown...","Gantt Chart, CPM and PERT","Optimisation, linear programming as an aid to decision making, transport and materials handling"]'::jsonb),
  ('Electronic Engineering', 'GET 502', 'Engineering Law', '500 Level', 'second', 2, false, 'Common Law: its history, definition, nature and division. Legislation, codification interpretation. Equity: definition and its main spheres. Law of contracts for Engineers: Forms of contract and criteria for selecting contractors; offer, acceptance, communication termination of contract. Terms of Contracts; suppliers'' duties - Damages and other Remedies. Termination/cancellation of contract Liquidation and Penalties; exemption clauses, safety and risk. Health and Safety. Duties of employers towards their employees. Duties imposed on employees. Fire precautions act. Design for safety. General principles of criminal law. Law of torts: definition, classification and liabilities. Patents: requirements, application, and infringement. Registered designs: application, requirements, types and infringement. Company law. Labour law and Industrial Law. Business registration.', '["Common Law: its history, definition, nature and division","Legislation, codification interpretation","Equity: definition and its main spheres","Law of contracts for Engineers: Forms of contract and criteria for selecting contractors","offer, acceptance, communication termination of contract","Terms of Contracts","suppliers'' duties - Damages and other Remedies","Termination/cancellation of contract Liquidation and Penalties"]'::jsonb),
  ('Electronic Engineering', 'CPE 501', 'Testing, Reliability and Maintainability', '500 Level', 'first', 2, false, 'Introduction to reliability, maintainability, availability, elementary reliability theory; application to power systems and electronic components; test characteristics of electrical and electronic components; types of fault; designing for higher reliability; packaging, mounting, ventilation; protection from humidity, dust.', '["Introduction to reliability, maintainability, availability, elementary reliability theory","application to power systems and electronic components","test characteristics of electrical and electronic components","types of fault","designing for higher reliability","packaging, mounting, ventilation","protection from humidity, dust"]'::jsonb),
  ('Electronic Engineering', 'CPE 502', 'Digital Signal Processing', '500 Level', 'second', 3, false, 'Discrete signals and Z-transform, digital fourier transform, fast fourier transform; the approximation problem in network theory; synthesis of low-pass filters; spectral transforms and their application in synthesis of high-pass and band-pass filters; digital filtering, digital transfer function aliasing, one-dimensional recursive and non-recursive filters; computer techniques in filter synthesis, realisation of filters in hardware and software; and basic image processing concepts.', '["Discrete signals and Z-transform, digital fourier transform, fast fourier transform","the approximation problem in network theory","synthesis of low-pass filters","spectral transforms and their application in synthesis of high-pass and band-pass filters","digital filtering, digital transfer function aliasing, one-dimensional recursive and non-recursive filters","computer techniques in filter synthesis, realisation of filters in hardware and software","and basic image processing concepts"]'::jsonb),
  ('Electronic Engineering', 'CPE 505', 'Digital System Design with VHDL', '500 Level', 'first', 2, false, 'Finite state machine: definition, mealy and Moore models, state diagram, state table, transition table; sequential circuits design using flip-flops, asynchronous and synchronous circuit design; algorithm state machine; design examples and exercises; structured design: design constructs, design levels, geometry-based interchange formats, computer-aided electronic system design tools, schematic circuit capture, hardware description languages, design process (simulation, synthesis), structural design decomposition; introduction to VHDL: VHDL language abstractions, design hierarchies, VHDL component, lexical description, VHDL source file, data types, data objects, language statements, concurrent VHDL, sequential VHDL, advanced features of VHDL (library, package and sub- programmes); structural level modelling, register-transfer level modelling, FSM with data path level modelling, algorithmic level modelling; introduction of ASIC, types of ASIC, ASIC design process, standard cell ASIC synthesis, FPGA design paradigm, FPGA synthesis, FPGA/CPLD architectures; VHDL Design: top-down design flow, verification, simulation alternatives, simulation speed, formal verification, recommendations for verification, writing RTL VHDL code for synthesis, top-down design with FPGA; VHDL synthesis, optimisation and mapping, constraints, technology library, delay calculation, synthesis tool, synthesis directives; and computer-aided design of logic circuits.', '["Finite state machine: definition, mealy and Moore models, state diagram, state table, transition table","sequential circuits design using flip-flops, asynchronous and synchronous circuit design","algorithm state machine","design examples and exercises","structured design: design constructs, design levels, geometry-based interchange formats, computer-aided...","introduction to VHDL: VHDL language abstractions, design hierarchies, VHDL component, lexical description,...","structural level modelling, register-transfer level modelling, FSM with data path level modelling,...","introduction of ASIC, types of ASIC, ASIC design process, standard cell ASIC synthesis, FPGA design..."]'::jsonb),
  ('Electronic Engineering', 'CPE 511', 'Machine Learning and Applications', '500 Level', 'first', 3, false, 'Introduction to machine learning; ; introduction to R or Python for machine learning: statistics for analytics: descriptive statistics, inferential statistics, estimation and hypothesis testing, ANOVA; machine learning: unsupervised learning - clustering, supervised learning - classification, decision trees, random forest, and model performance measures.', '["Introduction to machine learning","introduction to R or Python for machine learning: statistics for analytics: descriptive statistics,...","machine learning: unsupervised learning - clustering, supervised learning - classification, decision..."]'::jsonb),
  ('Electronic Engineering', 'CPE 514', 'Professional Practice and Ethics', '500 Level', 'second', 2, false, 'Engineering profession: structure and specializations (Nigeria and abroad), engineering basics, development of engineering profession, ethics and computer engineering, strands in ethical thinking, organisations and their structures: limited liability companies, private and public, partnerships, sole traders, special features of limited companies, responsibilities of directors; company finance: the need for capital; investment and working capital; sources of funds; equity capital and loan capital, cash flow and its importance, costing: fixed costs and variable costs; overheads; opportunity costs; depreciation; problems of cost allocation; budgeting; assessment of capital investment; discounted cash flow analysis, with particular reference to investment in software tolls and new product development; financial accounts: balance sheets, profit and loss accounts, cash flow statements; the treatment of software in company accounts; ownership of rights in software as goodwill; anatomy of software house: the company, company structure, management of staff, producing of budget, monitoring financial performance, producing budgets, computer contracts and intellectual property rights: the nature and types of intellectual property; intellectual property law (confidentiality, copyright, trademarks, and patents) and implications for the computing, computer engineering and software industry; computer misuse and criminal law: computing and criminal activity, reform and criminal law, categories of misuse, computer fraud, unauthorized access ;data protection: data protection and privacy, the impact of the internet; sociology of data management/processing: generation, users, regulation/control and general management; Professional and industry codes of conduct(local and international).', '["Engineering profession: structure and specializations (Nigeria and abroad), engineering basics,...","company finance: the need for capital","investment and working capital","sources of funds","equity capital and loan capital, cash flow and its importance, costing: fixed costs and variable costs","overheads","opportunity costs","depreciation"]'::jsonb),
  ('Electronic Engineering', 'CPE 599', 'Final Year Project', '500 Level', 'first', 6, false, '', '[]'::jsonb),
  ('Electrical Engineering', 'GET 101', 'Engineer in Society', '100 Level', 'first', 1, false, 'History, evolution and philosophy of science. engineering and technology. The engineering profession - engineering family (engineers, technologists, technicians and craftsmen), professional bodies and societies. Engineers'' code of conduct and ethics, and engineering literacy. Sustainable development goals (SDGs), innovation, infrastructures and nation building - economy, politics, business. Safety and risk analysis in engineering practice. Engineering competency skills - curriculum overview, technical, soft and digital skills. Guest seminars and invited lectures from different engineering professional associations.', '["History, evolution and philosophy of science","engineering and technology","The engineering profession - engineering family (engineers, technologists, technicians and craftsmen),...","Engineers'' code of conduct and ethics, and engineering literacy","Sustainable development goals (SDGs), innovation, infrastructures and nation building - economy, politics,...","Safety and risk analysis in engineering practice","Engineering competency skills - curriculum overview, technical, soft and digital skills","Guest seminars and invited lectures from different engineering professional associations"]'::jsonb),
  ('Electrical Engineering', 'GET 102', 'Introduction to Solid Modelling Design and Engineering', '100 Level', 'second', 2, false, 'Introduction to design thinking and engineering graphics. First and third angle orthogonal projections. Isometric projections; sectioning, conventional practices, conic sections and development. Freehand and guided sketching - pictorial and orthographic. Visualisation and solid modelling in design, prototyping and product-making. User interfaces in concrete terms. Design, drawing, animation, rendering and simulation workspaces. Sketching of 3D objects. Viewports and sectioning to shop drawings in orthographic projections and perspectives. Automated viewports. Sheet metal and surface modelling. Material selection and rendering. This course will use latest professional design tools such as fusion 360, solid works, solid edge or equivalent.', '["Introduction to design thinking and engineering graphics","First and third angle orthogonal projections","Isometric projections","sectioning, conventional practices, conic sections and development","Freehand and guided sketching - pictorial and orthographic","Visualisation and solid modelling in design, prototyping and product-making","User interfaces in concrete terms","Design, drawing, animation, rendering and simulation workspaces"]'::jsonb),
  ('Electrical Engineering', 'TEL 100', 'Introduction to Electrical Engineering', '100 Level', 'second', 2, false, '', '[]'::jsonb),
  ('Electrical Engineering', 'ENT 211', 'Entrepreneurship and Innovation', '200 Level', 'first', 2, false, 'The concept of entrepreneurship (entrepreneurship, intrapreneurship/corporate entrepreneurship); theories, rationale and relevance of entrepreneurship (Schumpeterian and other perspectives, risk-taking, necessity and opportunity-based entrepreneurship, and creative destruction); characteristics of entrepreneurs (opportunity seeker, risk-taker, natural and nurtured, problem solver and change agent, innovator and creative thinker); entrepreneurial thinking (critical thinking, reflective thinking and creative thinking). Innovation', '["The concept of entrepreneurship (entrepreneurship, intrapreneurship/corporate entrepreneurship)","theories, rationale and relevance of entrepreneurship (Schumpeterian and other perspectives, risk-taking,...","characteristics of entrepreneurs (opportunity seeker, risk-taker, natural and nurtured, problem solver and...","entrepreneurial thinking (critical thinking, reflective thinking and creative thinking)","Innovation"]'::jsonb),
  ('Electrical Engineering', 'GET 201', 'Applied Electricity I', '200 Level', 'first', 3, false, 'Fundamental concepts: Electric fields, charges, magnetic fields. current, B-H curves Kirchhoff''s laws, superposition. Thevenin, Norton theorems, Reciprocity, RL, RC, RLC circuits. DC, AC bridges, Resistance, Capacitance, Inductance measurement, Transducers, Single phase circuits, Complex j - notation, AC circuits, impedance, admittance, susceptance.', '["Fundamental concepts: Electric fields, charges, magnetic fields","current, B-H curves Kirchhoff''s laws, superposition","Thevenin, Norton theorems, Reciprocity, RL, RC, RLC circuits","DC, AC bridges, Resistance, Capacitance, Inductance measurement, Transducers, Single phase circuits,..."]'::jsonb),
  ('Electrical Engineering', 'GET 203', 'Solid Modelling and Design Engineering', '200 Level', 'first', 2, true, 'Projection of lines, auxiliary views and mixed projection. Preparation of detailed working production drawing; semi-detailed drawings, conventional presentation methods. Solid, surface and shell modeling. Faces, bodies and surface intersections. Component-based design. Component assembly and motion constraints. Constrained motions and animation. Introduction to electronics modeling. Electronics board layout preparation, Component libraries and Schematic design. Parametric modeling and adaptive design. Simulation for material optimization. Designing for manufacturing. Additive and subtractive manufacturing. Production for 3-D printing, Laser cutting and CNC machinery.Arrangement of engineering components to form a working plant (Assembly Drawing of a Plant).', '["Projection of lines, auxiliary views and mixed projection","Preparation of detailed working production drawing","semi-detailed drawings, conventional presentation methods","Solid, surface and shell modeling","Faces, bodies and surface intersections","Component-based design","Component assembly and motion constraints","Constrained motions and animation"]'::jsonb),
  ('Electrical Engineering', 'GET 204', 'Students Workshop Practice', '200 Level', 'second', 2, true, 'The course comprises general, mechanical and electrical components: supervised hands-on experience in safe usage of tools and machines for selected tasks; Use of measuring instruments (calipers, micrometers, gauges, sine bar, wood planners, saws, sanders, and pattern making). Machine shop: lathe work shaping, milling, grinding, reaming, metal spinning. Hand tools, gas and arc welding, cutting, brazing and soldering. Foundry practice.Industrial safety and accident prevention, ergonomics, metrology. Casting processes. Metal forming processes: hot-working and cold-working processes (forging, press- tool work, spinning, etc.). Metal joining processes(welding, brazing and soldering). Heat treatment. Material removal processes. machine tools and classification. Simple theory of metal cutting. Tool action and cutting forces. Introduction to CNC machines. Supervised identification, use and care of various electrical and electronic components such as resistors, inductors, capacitors, diodes and transistors. Exposure to different electric circuits, wiring schemes, analogue and digital electrical and electronic measurements. Household and industrial energy consumption measurements. Practical energy conservation principles.', '["The course comprises general, mechanical and electrical components: supervised hands-on experience in safe...","Use of measuring instruments (calipers, micrometers, gauges, sine bar, wood planners, saws, sanders, and...","Machine shop: lathe work shaping, milling, grinding, reaming, metal spinning","Hand tools, gas and arc welding, cutting, brazing and soldering","Foundry practice.Industrial safety and accident prevention, ergonomics, metrology","Casting processes","Metal forming processes: hot-working and cold-working processes (forging, press- tool work, spinning, etc.)","Metal joining processes(welding, brazing and soldering)"]'::jsonb),
  ('Electrical Engineering', 'GET 206', 'Fundamentals of Thermodynamics', '200 Level', 'second', 3, false, 'Basic concepts, definitions and laws (quantitative relations of Zeroth, first, second and third laws of thermodynamics). Properties of pure substances: the two-property rule (P-V-T behaviour of pure substances and perfect gases); state diagrams. The principle of corresponding state; compressibility relations; reduced pressure; reduced volume; temperature; pseudo-critical constants. The ideal gas: specific heat, polytropic processes. Ideal gas cycles; Carnot; thermodynamic cycles, turbines, steam and gas, refrigeration. The first law of thermodynamics - heat and work, applications to open and closed systems. The steady flow energy equation (Bernoulli''s equation) and application. Second law of thermodynamics, heat cycles and efficiencies.', '["Basic concepts, definitions and laws (quantitative relations of Zeroth, first, second and third laws of...","Properties of pure substances: the two-property rule (P-V-T behaviour of pure substances and perfect gases)","state diagrams","The principle of corresponding state","compressibility relations","reduced pressure","reduced volume","temperature"]'::jsonb),
  ('Electrical Engineering', 'GET 207', 'Applied Mechanics', '200 Level', 'first', 3, false, 'Forces, moments, couples. Equilibrium of simple structures and machine parts. Friction. First and second moments of area; centroids. Kinematics of particles and rigid bodies in plane motion. Newton''s laws of motion. Kinetic energy and momentum analyse.', '["Forces, moments, couples","Equilibrium of simple structures and machine parts","First and second moments of area","centroids","Kinematics of particles and rigid bodies in plane motion","Newton''s laws of motion","Kinetic energy and momentum analyse"]'::jsonb),
  ('Electrical Engineering', 'GET 209', 'Engineering Mathematics I', '200 Level', 'first', 3, false, 'Limits, continuity, differentiation, introduction to linear first order differential equations, partial and total derivatives, composite functions, matrices and determinants, vector algebra, vector calculus, directional derivatives.', '["Limits, continuity, differentiation, introduction to linear first order differential equations, partial..."]'::jsonb),
  ('Electrical Engineering', 'GET 210', 'Engineering Mathematics II', '200 Level', 'second', 3, false, 'Introduction to ordinary differential equations (ODEs); theory, applications, methods of solution; second order differential equations. Advanced topics in calculus (vectors and vector-valued function, line integral, multiple integral and their applications). Elementary complex analysis including functions of complex variables, limits and continuity. Derivatives, differentiation rules and differentiation of integrals. Cauchy-Riemann equation, harmonic functions, basic theory of conformal mapping, transformation and mapping and its applications to engineering problems. Special functions.', '["Introduction to ordinary differential equations (ODEs)","theory, applications, methods of solution","second order differential equations","Advanced topics in calculus (vectors and vector-valued function, line integral, multiple integral and...","Elementary complex analysis including functions of complex variables, limits and continuity","Derivatives, differentiation rules and differentiation of integrals","Cauchy-Riemann equation, harmonic functions, basic theory of conformal mapping, transformation and mapping...","Special functions"]'::jsonb),
  ('Electrical Engineering', 'GET 211', 'Computing and Software Engineering', '200 Level', 'first', 3, false, 'Introduction to computers and computing; computer organisation - data processing, memory, registers and addressing schemes; Boolean algebra; floating-point arithmetic; representation of non-numeric information; problem-solving and algorithm development; coding (solution design using flowcharts and pseudo codes). Data models and data structures; computer software and operating system; computer operators and operators precedence; components of computer programs; introduction to object oriented, structured and visual programming; use of MATLAB in engineering applications. ICT fundamentals, Internet of Things (IoT). Elements of software engineering.', '["Introduction to computers and computing","computer organisation - data processing, memory, registers and addressing schemes","Boolean algebra","floating-point arithmetic","representation of non-numeric information","problem-solving and algorithm development","coding (solution design using flowcharts and pseudo codes)","Data models and data structures"]'::jsonb),
  ('Electrical Engineering', 'TEL 202', 'Applied Electricity II', '200 Level', 'second', 3, false, 'Power factor, Power in AC circuit, Resonance in RLC series and parallel circuit, Three Phase Circuits: Voltages of three balanced phase system, delta and star connection, relationship between line and phase quantities, phasor diagrams. DC Machines: Construction, Basic concepts of winding (Lap and wave); DC generator: Principle of operation, EMF equation, characteristics (open circuit, load) DC motors: Principle of operation, Torque Equation, Speed Torque Characteristics (shunt and series machine); Single Phase Transformer: Constructional parts, Types of transformers, Emf equation, No Load no load and on load operation, phasor diagram and equivalent circuit, losses of a transformer, regulation and efficiency calculation; Three Phase Induction Motor: Types, Construction, production of rotating field, principle of operation, Slip and Frequency, rotor emf and current, Equivalent circuit and phasor diagram, Torque Slip characteristics torque-speed characteristics; General Structure of Electrical Power System: Power generation to distribution through overhead lines and underground cables with single line diagram, Earthing of Electrical Equipment, Electrical Wiring Practice.', '["Power factor, Power in AC circuit, Resonance in RLC series and parallel circuit, Three Phase Circuits:...","DC Machines: Construction, Basic concepts of winding (Lap and wave)","DC generator: Principle of operation, EMF equation, characteristics (open circuit, load) DC motors:...","Single Phase Transformer: Constructional parts, Types of transformers, Emf equation, No Load no load and...","Three Phase Induction Motor: Types, Construction, production of rotating field, principle of operation,...","General Structure of Electrical Power System: Power generation to distribution through overhead lines and..."]'::jsonb),
  ('Electrical Engineering', 'EEE 208', 'Electrical Engineering Materials', '200 Level', 'second', 3, false, 'Atomic Structure and Bonding: the internal structure of the atom will be examined and will include the electron orbital model of atomic structure. This will be extended to explain the different types of bonding, which occurs within materials. Crystal Structure: The main types of crystal lattices will be examined and the defects, which may occur, will be described. Properties of Materials: The main properties of materials will be described as will the methods used to quantify them: Free electron motion in static electric and magnetic fields, electronic structure of matter, conductivity in crystalline solids; Theory of energy hands in conductors, insulators and semi-conductors: electrons in metals and electron emissions; carriers and transport phenomena in semi-conductors, characteristics of some electron and resistors, diodes, transistors, photo cell and light emitting diode; Elementary discrete devices fabrication techniques and IC technology. 300 Level', '["Atomic Structure and Bonding: the internal structure of the atom will be examined and will include the...","This will be extended to explain the different types of bonding, which occurs within materials","Crystal Structure: The main types of crystal lattices will be examined and the defects, which may occur,...","Properties of Materials: The main properties of materials will be described as will the methods used to...","Theory of energy hands in conductors, insulators and semi-conductors: electrons in metals and electron...","carriers and transport phenomena in semi-conductors, characteristics of some electron and resistors,...","Elementary discrete devices fabrication techniques and IC technology","300 Level"]'::jsonb),
  ('Electrical Engineering', 'ENT 312', 'Venture Creation', '300 Level', 'second', 2, false, 'Opportunity identification (sources of business opportunities in Nigeria, environmental scanning, demand and supply gap/unmet needs/market gaps/market research, unutilised', '["Opportunity identification (sources of business opportunities in Nigeria, environmental scanning, demand..."]'::jsonb),
  ('Electrical Engineering', 'GET 301', 'Engineering Mathematics III', '300 Level', 'first', 3, false, '', '[]'::jsonb),
  ('Electrical Engineering', 'GET 304', 'Technical Writing and Communication', '300 Level', 'second', 3, false, 'A brief review of common pitfalls in writing. Principles of clear writing (punctuations and capitalization). Figures of speech. Units of grammar. Tenses and verb agreement. Active and passive sentences Lexis and structure Fog Index concept. Skills for communication and communication algorithm. Types and goals of communication; Interpersonal communication; features and the Finger Model or A,B,C,D,E of good interpersonal communication (accuracy of technical terms, brevity of expression, clarity of purpose, directness of focus and effectiveness of the report). Language and organisation of reports. Technical report writing skills(steps, problems in writing, distinguishing technical and other reports, significance, format and styles of writing technical reports). Different formats for communication; styles of correspondences - business report and proposal, business letter, memorandum, e-mails, etc. Proposals for projects and research; format, major steps and tips of grant-oriented proposals. Research reports(competency, major steps, components and formats of research reports and publishable communication). Sources and handling of data, tables, figures, equations and references in a report. Presentation skills; overview, tips, organisation, use of visual aids and practising of presentation. Intellectual property rights in research reports. Case studies of major engineering designs, proposals and industrial failures with professional presentation of reports.', '["A brief review of common pitfalls in writing","Principles of clear writing (punctuations and capitalization)","Figures of speech","Units of grammar","Tenses and verb agreement","Active and passive sentences Lexis and structure Fog Index concept","Skills for communication and communication algorithm","Types and goals of communication"]'::jsonb),
  ('Electrical Engineering', 'GET 305', 'Engineering Statistics and Data Analytics', '300 Level', 'first', 3, false, 'Descriptive statistics, frequency distribution, populations and sample, central tendency, variance data sampling, mean, median, mode, mean deviation and percentiles. Probability. Binomial, Poisson hyper-geometric and normal distributions. Statistical inference intervals,', '["Descriptive statistics, frequency distribution, populations and sample, central tendency, variance data...","Probability","Binomial, Poisson hyper-geometric and normal distributions","Statistical inference intervals,"]'::jsonb),
  ('Electrical Engineering', 'GET 306', 'Renewable Energy Systems and Technologiy', '300 Level', 'second', 3, false, 'Current and potential future energy systems in Nigeria and globally - resources, extraction, concepts in energy conversion systems; parallels and differences in various conversion systems and end-use technologies, with emphasis on meeting 21st-century national, regional and global energy needs in a sustainable manner. Various energy technologies in each fuel cycle stage for fossil (oil, gas, synthetic), nuclear (fission and fusion) and renewable (solar, biomass, wind, hydro, and geothermal). Energy types, storage, transmission and conservation. Analysis of energy mixes within an engineering, economic and social context. Sustainable energy; emphasise sustainability in general and in the overall concept of sustainable development and the link this has with sustainable energy as the fundamental benefit of renewable energy. Practical Contents Simple measurement of solar radiation, bomb calorimeter determination of calorific value of fuels and biomass; measurement of the velocity of wind, waves and the energy that abound in them; laboratory production of biogas and determination of energy available in it; simple conversion of solar energy to electricity; transesterification of edible oil into biodiesel; simulation of geothermal energy; Geiger-Muller or Scintillation Counters'' determination of uranium or thorium energy; simple solid or salt storage of energy; hybrid application of renewable energy.', '["Current and potential future energy systems in Nigeria and globally - resources, extraction, concepts in...","parallels and differences in various conversion systems and end-use technologies, with emphasis on meeting...","Various energy technologies in each fuel cycle stage for fossil (oil, gas, synthetic), nuclear (fission...","Energy types, storage, transmission and conservation","Analysis of energy mixes within an engineering, economic and social context","Sustainable energy","emphasise sustainability in general and in the overall concept of sustainable development and the link...","Practical Contents Simple measurement of solar radiation, bomb calorimeter determination of calorific..."]'::jsonb),
  ('Electrical Engineering', 'GET 307', 'Introduction to Artificial Intelligence, Machine Learning and Convergent Technologies', '300 Level', 'first', 3, false, '', '[]'::jsonb),
  ('Electrical Engineering', 'EEE 321', 'Analogue Electronic Circuits', '300 Level', 'first', 2, false, 'Single-stage transistor amplifiers using BJT and FET Equivalent circuits and calculation of current gain, voltage gain, power gain, input and output impedance. Operational Amplifiers: Description, parameters and applications. Feedback, broadband and narrowband amplifiers. Power amplifiers. Voltage and current stabilizing circuits. Voltage amplifiers, multi-stage amplifiers using BJTs and FETs.', '["Single-stage transistor amplifiers using BJT and FET Equivalent circuits and calculation of current gain,...","Operational Amplifiers: Description, parameters and applications","Feedback, broadband and narrowband amplifiers","Power amplifiers","Voltage and current stabilizing circuits","Voltage amplifiers, multi-stage amplifiers using BJTs and FETs"]'::jsonb),
  ('Electrical Engineering', 'TEL 303', 'Electric Circuit Theory', '300 Level', 'first', 2, false, 'Basic Concepts: Introduction, Systems of Units, Charge and Current, Voltage, Power and Energy, Circuit Elements. Basic Laws: Ohm''s Laws, Nodes, Branches, and Loops, Kirchhoff''s Laws, Series Resistors and Voltage Division, Parallel Resistors and Current Division, Wye-Delta Transformations. Methods of Analysis: Nodal Analysis, Nodal Analysis with Voltage Sources, Mesh Analysis, Mesh Analysis with Current Sources, Nodal and Mesh Analyses by Inspection, Nodal Versus Mesh Analysis. Circuit Theorems: Linearity Property, Superposition, Source Transformation, Thevenin''s Theorem, Norton''s Theorem, Derivations of Thevenin''s and Norton''s Theorems, Maximum Power Transfer. Operational Amplifiers: Operational Amplifiers, Ideal Op Amp, Inverting Amplifier, Noninverting Amplifier, Summing Amplifier, Difference Amplifier, Cascaded Op Amp Circuits, Op Amp Circuit Analysis. Capacitors and Inductors: Series and Parallel Capacitors, Inductors, Series and Parallel Inductors. First Order Circuits: The Source-free RC Circuit, The Source-free RL Circuit, Singularity Functions, Step Response of an RC Circuit, Step Response of an RL Circuit, First-order Op Amp Circuits. Second Order Circuits: Finding Initial and Final Values, The Source-Free Series RLC Circuit, The Source-Free Parallel RLC Circuit, Step Response of a Series RLC Circuit, Step Response of a Parallel Circuit, General Second-Order Circuits, Second-Order Op Amp Circuits: Sinusoidal steady-state analysis. AC circuit power analysis. Polyphase circuits. Magnetically coupled circuits; Complex frequency and Laplace transform; Circuit analysis and the s-Domain; Frequency response: Bode Diagram. Fourier circuit analysis.', '["Basic Concepts: Introduction, Systems of Units, Charge and Current, Voltage, Power and Energy, Circuit...","Basic Laws: Ohm''s Laws, Nodes, Branches, and Loops, Kirchhoff''s Laws, Series Resistors and Voltage...","Methods of Analysis: Nodal Analysis, Nodal Analysis with Voltage Sources, Mesh Analysis, Mesh Analysis...","Circuit Theorems: Linearity Property, Superposition, Source Transformation, Thevenin''s Theorem, Norton''s...","Operational Amplifiers: Operational Amplifiers, Ideal Op Amp, Inverting Amplifier, Noninverting Amplifier,...","Capacitors and Inductors: Series and Parallel Capacitors, Inductors, Series and Parallel Inductors","First Order Circuits: The Source-free RC Circuit, The Source-free RL Circuit, Singularity Functions, Step...","Second Order Circuits: Finding Initial and Final Values, The Source-Free Series RLC Circuit, The..."]'::jsonb),
  ('Electrical Engineering', 'TEL 304', 'Measurements and Instrumentations', '300 Level', 'second', 2, false, 'Introduction: Significance of Measurement and block diagram of Measurement System, Static characteristics- Accuracy, Precision, Sensitivity, Linearity, Repeatability, Reproducibility, Resolution, Threshold, Drift, Stability, Dead zone, hysteresis, Dynamic Characteristics- speed of response, measuring lag, fidelity, dynamic error, Types of Errors - Gross error, systematic errors, Random errors. Measuring Instruments: PMMC, DC voltmetre and current metres and its Extension ranges, True RMS Responding Voltmeter, Average responding rectifier type voltmetre, electronic', '["Introduction: Significance of Measurement and block diagram of Measurement System, Static characteristics-...","Measuring Instruments: PMMC, DC voltmetre and current metres and its Extension ranges, True RMS Responding..."]'::jsonb),
  ('Electrical Engineering', 'TEL 305', 'Electrical Machines', '300 Level', 'first', 3, false, 'DC Machine, Introduction to Machinery Principles, Rotational motion, Newton''s Law and power relationships, the Magnetic field, Magnetic Circuit with air gap, Faraday''s law, Production of induced force on wire, Induced voltage on a conductor moving in a magnetic field, Linear DC machine.; DC Machinery Fundamentals: Simple rotating loop between curved pole faces, Commutation, Construction, Simple armature winding, Armature reaction, Interpoles, compensating winding and brush shifting, Internal generated voltage and induced torque equations of real machines; DC Generators, Introduction, Voltage regulation, Magnetization curve, Equivalent circuits, Working and characteristics of separately excited, shunt, series and compounded generators, Parallel operations of direct current generators; DC Motors, Introduction, Speed regulation, Equivalent Circuits, Working and Characteristics of separately excited, Shunt and Permanent magnet, Working and Characteristics of series and compounded motors, Torque-speed Equations, Efficiency calculations, Stepper Motor and Drive circuit.; AC Machines Topics, Transformer Fundamentals, Importance of transformers, Types and construction, The ideal transformer, Leakage reactance, Theory and operation of single phase transformer, Losses and phasor diagram, the equivalent circuit of a real transformer, No load', '["DC Machine, Introduction to Machinery Principles, Rotational motion, Newton''s Law and power relationships,...","DC Machinery Fundamentals: Simple rotating loop between curved pole faces, Commutation, Construction,...","DC Generators, Introduction, Voltage regulation, Magnetization curve, Equivalent circuits, Working and...","DC Motors, Introduction, Speed regulation, Equivalent Circuits, Working and Characteristics of separately...","AC Machines Topics, Transformer Fundamentals, Importance of transformers, Types and construction, The..."]'::jsonb),
  ('Electrical Engineering', 'TEL 324', 'Electromagnetic Theory', '300 Level', 'second', 2, false, 'Electromagnetics - Motion and Vector algebra, Integral calculus, Curvilinear coordinates, Divergence and Stokes''s theorem, Coulomb''s law, Electric field; Electrostatics - Gauss''s Law, Electric potential, Conductors, Dielectrics, Capacitance, Capacitors, Electrostatics Energy and Forces, Poisson''s Equation, Method of Images, Boundary Value Problems, Current Density, Ohm''s Law, Kirchhoff''s and Joule''s Laws; Magnetostatics - Vector Magnetic Potential, The Biot-Savart Law, the Magnetic Dipole, Magnetic Materials, Boundary Conditions, Inductors, Energy, Forces; Electrodynamics - Electromagnetic Induction, Maxwell''s equations, Potential Functions, Boundary Conditions, Wave Equations; Review of EM laws in integral form; Gauss law. Ampere''s law and Faraday''s laws; uniform em plane waves: Magnetic fields in and around current carrying conductors. Conduction and displacement currents; Derivation of Maxwell''s equations in curl form from Faraday''s and Ampere''s laws; Time varying electric and magnetic fields in free space the wave equation; Plane waves in vacuum, dielectric conducting and lossy media; Skin effect; Polarisation of waves; Poynting vector and energy propagation in free space; Boundary conditions; Plane waves in unbounded dielectric media. Reflection and transmission of plane waves. Em radiating systems: Antennae - isotropic antenna, elementary dipole near the far fields. Antenna parametres. Half-wave antenna. Practical antenna e.g. loop, horn and parabolic 400 Level GET 402 Engineering Project I (2 Units: C; PH 90) Learning Outcomes At the end of this course, the students should be able to: 1. Complete the design phase of a complex engineering problem sourced from industry or community during the SIWES III programme. 2. Demonstrate the connection between engineering product-making and the theoretical courses they have learned following the applicable industry best practices.', '["Electromagnetics - Motion and Vector algebra, Integral calculus, Curvilinear coordinates, Divergence and...","Electrostatics - Gauss''s Law, Electric potential, Conductors, Dielectrics, Capacitance, Capacitors,...","Magnetostatics - Vector Magnetic Potential, The Biot-Savart Law, the Magnetic Dipole, Magnetic Materials,...","Electrodynamics - Electromagnetic Induction, Maxwell''s equations, Potential Functions, Boundary...","Review of EM laws in integral form","Gauss law","Ampere''s law and Faraday''s laws","uniform em plane waves: Magnetic fields in and around current carrying conductors"]'::jsonb),
  ('Electrical Engineering', 'TEL 322', 'Electrical Energy Systems', '300 Level', 'second', 2, false, 'Generation of electric energy: Sources of energy. Heat value of fuels. Thermal stations. Hydroelectric stations. Nuclear stations. Economics of power supply: Fixed and running charges in electric power production. Load curves and load duration curves including concept of base, intermediate and peak load. Definition of load factor, maximum demand, Diversity factor and their effects on generation. Distribution system: Survey of power system components: feeders, distributors, services mains, radial and ring-man systems. Voltage drop in distribution systems. Per-unit qualities. Overhead transmission system: Conductors and insulators. Transmission line parameters. Resistance, inductance and capacitance. Skin effect. Corona discharge. Stringing: Calculation of sag and tension. Stringing chart and performance. Representation of short and long power lines. Underground cables: Types. Inductance of concentric cables. Capacitance of single-core and three-core cables. Thermal characteristics. Sheath currents.', '["Generation of electric energy: Sources of energy","Heat value of fuels","Thermal stations","Hydroelectric stations","Nuclear stations","Economics of power supply: Fixed and running charges in electric power production","Load curves and load duration curves including concept of base, intermediate and peak load","Definition of load factor, maximum demand, Diversity factor and their effects on generation"]'::jsonb),
  ('Electrical Engineering', 'TEL 421', 'Control Engineering', '400 Level', 'first', 2, false, 'Feedback concept, advantages, system classification, structures; Control system components - mechanical, electronic hydraulic, thermal, position control; Transient analysis of servo- mechanism, signal regulators compensation techniques; Series/parallel feedback controllers. System transfer functions, signal flow graphs, stability, Routh-Hurwitz criteria.', '["Feedback concept, advantages, system classification, structures","Control system components - mechanical, electronic hydraulic, thermal, position control","Transient analysis of servo- mechanism, signal regulators compensation techniques","Series/parallel feedback controllers","System transfer functions, signal flow graphs, stability, Routh-Hurwitz criteria"]'::jsonb),
  ('Electrical Engineering', 'TEL 423', 'Power Electronics', '400 Level', 'first', 2, false, 'The basics of three-phase circuits, connections, voltage and current analysis and real and reactive power calculations; the fundamentals of electricity conversion from the form supplied by the source to the forms required by the load; power electronic conversion techniques, including the basic converters (DC-DC, AC-DC and DC-AC) and their power switching and control methods; the methods of circuit analysis applicable to switched mode circuits; essential properties of the relevant semiconductor devices; simple converters for practical applications. Topics: Characteristics of power devices; DC-DC converters; AC Current, Voltage and Power; Effects of power electronics on AC power Rectifiers (AC-DC converters) and Inverters (DC-AC converters).', '["The basics of three-phase circuits, connections, voltage and current analysis and real and reactive power...","the fundamentals of electricity conversion from the form supplied by the source to the forms required by...","power electronic conversion techniques, including the basic converters (DC-DC, AC-DC and DC-AC) and their...","the methods of circuit analysis applicable to switched mode circuits","essential properties of the relevant semiconductor devices","simple converters for practical applications","Topics: Characteristics of power devices","DC-DC converters"]'::jsonb),
  ('Electrical Engineering', 'TEL 401', 'Advanced Renewable Energy Systems', '400 Level', 'first', 2, false, 'Energy and civilization, fossil fuels: availability and depletion, Nuclear Energy, Global Warming, Green and Renewable Energy Sources. Estimates of energy costs, components of electric grid, electric energy outlook in Nigeria. Distribution and generation technologies and economics. Fundamentals of Solar Power Systems Photovoltaic Power Conversion, Photovoltaic Material, Modelling of Photovoltaic Systems, Design of Photovoltaic Systems, Concentrated Solar Power. Fundamentals of wind power systems wind power conversion, modelling of wind power systems, design of wind systems. hydrogen energy, energy storage and other renewable energy sources. Integration of distribution and generation into the grid dc/ac inverters,', '["Energy and civilization, fossil fuels: availability and depletion, Nuclear Energy, Global Warming, Green...","Estimates of energy costs, components of electric grid, electric energy outlook in Nigeria","Distribution and generation technologies and economics","Fundamentals of Solar Power Systems Photovoltaic Power Conversion, Photovoltaic Material, Modelling of...","Fundamentals of wind power systems wind power conversion, modelling of wind power systems, design of wind...","hydrogen energy, energy storage and other renewable energy sources","Integration of distribution and generation into the grid dc/ac inverters,"]'::jsonb),
  ('Electrical Engineering', 'TEL 402', 'Software/Computer Applications in Electrical Engineering', '400 Level', 'second', 2, false, '', '[]'::jsonb),
  ('Electrical Engineering', 'GET 404', 'Engineering Valuation', '400 Level', 'second', 2, false, '', '[]'::jsonb),
  ('Electrical Engineering', 'GET 501', 'Engineering Project Management', '500 Level', 'first', 3, false, 'Project management fundamentals - definitions, project environment, nature and characteristics, development practice, management by objectives, and the centrality of engineering to projects, infrastructures, national and global development. The scope of project management - organisational, financial, planning and control, personnel management, labour and public relations, wages and salary administration and resource management. Identification of project stakeholders; beneficiaries and impacted persons - functions, roles, responsibilities. Project community relations, communication and change management. Project planning, control and timeliness;decision making, forecasting, scheduling, work breakdown structure (WBS), deliverables and timelines, logical frameworks (log frames), risk analysis, role of subject matter experts (SMEs), role conflicts; Gantt Chart, CPM and PERT. Optimisation, linear programming as an aid to decision making, transport and materials handling. Monitoring and Evaluation - key performance indices (KPIs); methods of economic and technical evaluation. Industrial psychology, ergonomics/human factors and environmental impact considerations in engineering project design and management. Project business case - financial, technical and sustainability considerations. Case studies, site visits and invited industry professional seminars. General principles of management and appraisal techniques. Breakthrough and control management theory; production and maintenance management. Training and manpower development. The manager and policy formulation, objective setting, planning, organising and controlling, motivation and appraisal of results.', '["Project management fundamentals - definitions, project environment, nature and characteristics,...","The scope of project management - organisational, financial, planning and control, personnel management,...","Identification of project stakeholders","beneficiaries and impacted persons - functions, roles, responsibilities","Project community relations, communication and change management","Project planning, control and timeliness;decision making, forecasting, scheduling, work breakdown...","Gantt Chart, CPM and PERT","Optimisation, linear programming as an aid to decision making, transport and materials handling"]'::jsonb),
  ('Electrical Engineering', 'GET 502', 'Engineering Law', '500 Level', 'second', 2, false, 'Common Law: its history, definition, nature and division. Legislation, codification interpretation. Equity: definition and its main spheres. Law of contracts for Engineers: Forms of contract and criteria for selecting contractors; offer, acceptance, communication termination of contract. Terms of Contracts; suppliers'' duties - Damages and other Remedies. Termination/cancellation of contract Liquidation and Penalties; exemption clauses, safety and risk. Health and Safety. Duties of employers towards their employees. Duties imposed on employees. Fire precautions act. Design for safety. General principles of criminal law. Law of torts: definition, classification and liabilities. Patents: requirements, application, and infringement. Registered designs: application, requirements, types and infringement. Company law. Labour law and Industrial Law. Business registration.', '["Common Law: its history, definition, nature and division","Legislation, codification interpretation","Equity: definition and its main spheres","Law of contracts for Engineers: Forms of contract and criteria for selecting contractors","offer, acceptance, communication termination of contract","Terms of Contracts","suppliers'' duties - Damages and other Remedies","Termination/cancellation of contract Liquidation and Penalties"]'::jsonb),
  ('Electrical Engineering', 'TEL 502', 'Electrical Services Design', '500 Level', 'second', 2, false, 'Basic Electrical Installations; Distribution system, regulations - IEE, NEC, Nigeria standards; Illumination, Cables - types, ratings, wirings system, earth protection; Auxilliary electrical systems - fire alarm, telephone, elevator circuits, proposals, contract document preparation; Design of electrical installations - domestic, industrial, commercial air conditioning.', '["Basic Electrical Installations","Distribution system, regulations - IEE, NEC, Nigeria standards","Illumination, Cables - types, ratings, wirings system, earth protection","Auxilliary electrical systems - fire alarm, telephone, elevator circuits, proposals, contract document...","Design of electrical installations - domestic, industrial, commercial air conditioning"]'::jsonb),
  ('Electrical Engineering', 'TEL 507', 'Electric Power Systems Engineering', '500 Level', 'first', 2, false, 'Basic single-phase modeling. Three phase system analysis. Three phase models of transmission lines. Three phase models of transformers. Formation of the system admittance matrix. Modeling of Static AC-DC Conversion Plant: Introduction. Rectification, inversion.', '["Basic single-phase modeling","Three phase system analysis","Three phase models of transmission lines","Three phase models of transformers","Formation of the system admittance matrix","Modeling of Static AC-DC Conversion Plant: Introduction","Rectification, inversion"]'::jsonb),
  ('Electrical Engineering', 'TEL 503', 'Energy Economy', '500 Level', 'first', 2, false, 'This course explores the theoretical and empirical perspectives on individual and industrial demand for energy, energy supply, energy markets, and public policies affecting energy markets. It discusses aspects of the oil, natural gas, electricity, and nuclear power sectors and examines energy tax, price regulation, deregulation, energy efficiency and policies for controlling emission. Minimum Academic Standards Equipment S/N Description of Equipment Remarks Basic Electrical Engineering Laboratory 1 Tubular fluorescent lamp set Or Equivalent 2 Energy metre 3 Single phase induction motor 4 Transformer 5 Load box, single phase resistive 6 Drilling machine Electrical Circuit Network and Device Laboratory 1 Network theorem kit Or Equivalent', '["This course explores the theoretical and empirical perspectives on individual and industrial demand for...","It discusses aspects of the oil, natural gas, electricity, and nuclear power sectors and examines energy...","Minimum Academic Standards Equipment S/N Description of Equipment Remarks Basic Electrical Engineering..."]'::jsonb),
  ('Electronic Engineering', 'ELE 101', 'Introduction to Electronic Design and Practice', '100 Level', 'first', 2, false, '', '[]'::jsonb),
  ('Electronic Engineering', 'ENT 211', 'Entrepreneurship and Innovation', '200 Level', 'first', 2, false, 'The concept of entrepreneurship (entrepreneurship, intrapreneurship/corporate entrepreneurship); theories, rationale and relevance of entrepreneurship (Schumpeterian and other perspectives, risk-taking, necessity and opportunity-based entrepreneurship, and creative destruction); characteristics of entrepreneurs (opportunity seeker, risk-taker, natural and nurtured, problem solver and change agent, innovator and creative thinker); entrepreneurial thinking (critical thinking, reflective thinking and creative thinking). Innovation (The concept of innovation, dimensions of innovation, change and innovation, knowledge and innovation). Enterprise formation, partnership and networking (basics of business plan, forms of business ownership, business registration and alliance formation, and joint ventures). Contemporary entrepreneurship issues (knowledge, skills and technology, intellectual property, virtual office and networking). Entrepreneurship in Nigeria (biography of inspirational entrepreneurs, youth and women entrepreneurship, entrepreneurship support institutions, youth enterprise networks and environmental and cultural barriers to entrepreneurship). Basic principles of e-commerce.', '["The concept of entrepreneurship (entrepreneurship, intrapreneurship/corporate entrepreneurship)","theories, rationale and relevance of entrepreneurship (Schumpeterian and other perspectives, risk-taking,...","characteristics of entrepreneurs (opportunity seeker, risk-taker, natural and nurtured, problem solver and...","entrepreneurial thinking (critical thinking, reflective thinking and creative thinking)","Innovation (The concept of innovation, dimensions of innovation, change and innovation, knowledge and...","Enterprise formation, partnership and networking (basics of business plan, forms of business ownership,...","Contemporary entrepreneurship issues (knowledge, skills and technology, intellectual property, virtual...","Entrepreneurship in Nigeria (biography of inspirational entrepreneurs, youth and women entrepreneurship,..."]'::jsonb),
  ('Electronic Engineering', 'GET 206', 'Fundamentals of Thermodynamics', '200 Level', 'second', 3, false, 'Basic concepts, definitions and laws (quantitative relations of Zeroth, first, second and third laws of thermodynamics). Properties of pure substances: the two-property rule (P-V-T behaviour of pure substances and perfect gases); state diagrams. The principle of', '["Basic concepts, definitions and laws (quantitative relations of Zeroth, first, second and third laws of...","Properties of pure substances: the two-property rule (P-V-T behaviour of pure substances and perfect gases)","state diagrams","The principle of"]'::jsonb),
  ('Electronic Engineering', 'GET 307', 'Introductionn to Artificial Intelligence, Machine Learning and Convergent Technologies', '300 Level', 'first', 3, false, '', '[]'::jsonb),
  ('Electronic Engineering', 'ELE 313', 'Analog Electronic circuits', '300 Level', 'first', 3, false, 'Review of Microelectronic Devices: Diode, BJT, JFET, and MOSFET; Large-signal behaviour and Small-signal models; Single-Transistor Amplifiers: Common-emitter/source, common- base/gate, and common-collector/drain; Biasing, small-signal gain, input resistance, and output resistance; Circuit simulation using pSpice; Multi-Transistor Amplifiers: Cascade, differential, and cascade; Biasing, small-signal gain, input resistance, and output resistance; Frequency Response, Gain/phase plots and Analysis; Negative Feedback: Effects on gain, input resistance, output resistance, noise, distortion, and bandwidth; Inverting and non- inverting op amps; Passive Filters and Active Filters: Low-pass, high-pass, band-pass, and band-reject, First-, second-, and higher-order; Non-linear Circuits: Rectifiers and peak detectors, Sinusoidal oscillators, Mono and bi-stable multivibrators, Waveform generators.', '["Review of Microelectronic Devices: Diode, BJT, JFET, and MOSFET","Large-signal behaviour and Small-signal models","Single-Transistor Amplifiers: Common-emitter/source, common- base/gate, and common-collector/drain","Biasing, small-signal gain, input resistance, and output resistance","Circuit simulation using pSpice","Multi-Transistor Amplifiers: Cascade, differential, and cascade","Biasing, small-signal gain, input resistance, and output resistance","Frequency Response, Gain/phase plots and Analysis"]'::jsonb),
  ('Electronic Engineering', 'ELE 318', 'Digital Electronic', '300 Level', 'second', 2, true, 'Introduction to Computing Systems; Switch Design; Boolean Algebra; Gate Design and Simplification; Building Blocks; Number Systems and Arithmetic; Latches and Registers; Counters; State Machines; Memory; Datapaths; Introductory Assembly Programming. Laboratory projects will include use of PC-based CAD environment that supports schematic capture, logic simulation, and HDL-based logic synthesis on FPGAs (field-programmable gate', '["Introduction to Computing Systems","Switch Design","Boolean Algebra","Gate Design and Simplification","Building Blocks","Number Systems and Arithmetic","Latches and Registers","State Machines"]'::jsonb),
  ('Electronic Engineering', 'ELE 324', 'Communication Principles', '300 Level', 'second', 3, true, '', '[]'::jsonb),
