-- UNN Faculty of Engineering: fill each department's outline from the NUC CCMAS 2023 handbooks
-- =============================================================================
-- Source: CCMAS 2023, Engineering and Technology (NUC; open access, CC BY-SA 3.0 IGO). The
-- handbook has a separate programme table for each engineering degree. Each table is mapped
-- to the matching UNN department, and the Computer Engineering table also goes to Electronic
-- Engineering (UNN's department is called "Electronic and Computer Engineering").
--   Agricultural and Biosystems -> Agricultural and Bioresources Engineering
--   Biomedical, Civil, Electrical, Electronic, Mechanical, Mechatronics -> same names
--   Computer Engineering -> Electronic Engineering
--   Materials and Metallurgical -> Metallurgical and Materials Engineering
-- ADDITIVE ONLY. A course is added to a department only when the department has neither
-- that course code nor a course with the same title. Nothing is removed or renamed. General
-- studies, mathematics, physics and chemistry courses are skipped here because the departments
-- already have them from their own handbooks and the code-change updates. SIWES courses are
-- skipped. Added rows are tagged 'NUC CCMAS 2023 (Engineering)' so they are easy to review.
-- Level comes from the course code; semester from the CCMAS rule (odd last digit = first,
-- even = second). Blank descriptions of existing rows with the same code are also filled.
-- Rows per programme: Agricultural and Bioresources Engineering 36; Biomedical Engineering 36; Civil Engineering 32; Electronic Engineering 55; Electrical Engineering 36; Mechanical Engineering 30; Mechatronic Engineering 34; Metallurgical and Materials Engineering 35.
-- =============================================================================
create temp table ccmas_eng (department text, course_code text, course_title text, level text,
  semester text, credit_units int, is_elective boolean, description text, topics jsonb);

   semester, credit_units, description, topics, contributor_name, is_elective)
select distinct on (e.department, e.course_code)
       e.course_code, e.course_title, 'University of Nigeria, Nsukka', 'Faculty of Engineering',
       e.department, e.level, e.semester, e.credit_units, e.description, e.topics,
       'NUC CCMAS 2023 (Engineering)', e.is_elective
  from ccmas_eng e
 where not exists (
         select 1 from public.course_outlines c
          where c.institution = 'University of Nigeria, Nsukka'
            and c.department = e.department
            and (c.course_code = e.course_code
                 or lower(regexp_replace(c.course_title, '[^a-zA-Z0-9]+', '', 'g'))
                  = lower(regexp_replace(e.course_title, '[^a-zA-Z0-9]+', '', 'g'))))
 order by e.department, e.course_code;

update public.course_outlines t
   set description = e.description,
       topics = case when t.topics is null or t.topics = '[]'::jsonb then e.topics else t.topics end
  from ccmas_eng e
 where t.institution = 'University of Nigeria, Nsukka'
   and t.department = e.department
   and t.course_code = e.course_code
   and e.description <> ''
   and coalesce(trim(t.description), '') = '';

select department, count(*) as courses,
       count(*) filter (where contributor_name = 'NUC CCMAS 2023 (Engineering)') as added_now
  from public.course_outlines
 where institution = 'University of Nigeria, Nsukka' and faculty = 'Faculty of Engineering'
 group by department order by department;
